-- ---------------------------------------------------------------------
-- 20260924000001_schema.sql
-- ---------------------------------------------------------------------
-- EasySesh: core schema
-- Money is stored as integer minor units (cents). Timestamps are timestamptz.
-- Nested listing data is jsonb with snake_case keys (matches the iOS encoder).

create extension if not exists btree_gist with schema extensions;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.user_role as enum ('artist', 'studio_owner', 'admin');
create type public.account_status as enum ('active', 'suspended', 'banned');
create type public.studio_status as enum ('draft', 'pending_review', 'changes_requested', 'approved', 'rejected', 'suspended');
create type public.booking_status as enum ('awaiting_payment', 'pending_approval', 'confirmed', 'declined', 'cancelled', 'completed', 'disputed', 'expired');
create type public.payment_status as enum ('unpaid', 'authorized', 'deposit_paid', 'paid', 'partially_refunded', 'refunded', 'failed', 'pay_at_studio');
create type public.payment_method as enum ('card', 'apple_pay', 'google_pay', 'cash');
create type public.transaction_kind as enum ('charge', 'balance', 'refund');
create type public.transaction_status as enum ('pending', 'succeeded', 'failed');
create type public.payout_status as enum ('scheduled', 'in_transit', 'paid', 'failed');
create type public.message_kind as enum ('text', 'system', 'booking');
create type public.report_target as enum ('user', 'studio', 'review', 'message', 'booking');
create type public.report_reason as enum ('fake', 'spam', 'abusive', 'inappropriate', 'fraud', 'no_show', 'other');
create type public.report_status as enum ('open', 'resolved', 'dismissed');
create type public.notification_kind as enum (
  'booking_confirmed', 'booking_changed', 'booking_cancelled', 'booking_declined', 'session_reminder',
  'refund_issued', 'review_reminder', 'booking_requested', 'new_review', 'payout_sent',
  'studio_approved', 'studio_rejected', 'studio_changes_requested', 'new_message', 'system'
);

-- ---------------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  role public.user_role not null default 'artist',
  status public.account_status not null default 'active',
  status_reason text,
  is_verified boolean not null default false,
  settings jsonb not null default '{}'::jsonb,
  stripe_customer_id text,
  -- GDPR: which version of the terms/privacy policy the user accepted, and when.
  accepted_terms_version text,
  accepted_terms_at timestamptz,
  created_at timestamptz not null default now()
);

create table public.artist_profiles (
  id uuid primary key references public.profiles (id) on delete cascade,
  artist_name text not null default '',
  genres text[] not null default '{}',
  city text not null default '',
  bio text not null default '',
  avatar_url text,
  links jsonb not null default '[]'::jsonb,
  is_verified boolean not null default false,
  updated_at timestamptz not null default now()
);

create table public.device_tokens (
  token text primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  platform text not null default 'ios',
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Studios
-- ---------------------------------------------------------------------------
create table public.studios (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  name text not null default '',
  tagline text not null default '',
  description text not null default '',
  photo_urls text[] not null default '{}',
  video_url text,
  address jsonb not null default '{"street":"","postal_code":"","city":"","area":"","country":""}'::jsonb,
  latitude double precision not null default 0,
  longitude double precision not null default 0,
  contact jsonb not null default '{"phone":"","email":"","website":""}'::jsonb,
  timezone text not null default 'Europe/Athens',
  currency text not null default 'EUR' check (currency ~ '^[A-Z]{3}$'),
  price_from integer not null default 0 check (price_from >= 0),
  session_types jsonb not null default '[]'::jsonb,
  add_ons jsonb not null default '[]'::jsonb,
  facilities text[] not null default '{}',
  equipment jsonb not null default '[]'::jsonb,
  engineers jsonb not null default '[]'::jsonb,
  capacity integer not null default 4 check (capacity > 0),
  genres text[] not null default '{}',
  opening_hours jsonb not null default '[]'::jsonb,
  rules text[] not null default '{}',
  booking_policy jsonb not null default '{}'::jsonb,
  status public.studio_status not null default 'draft',
  is_active boolean not null default false,
  is_verified boolean not null default false,
  admin_note text,
  rating_average double precision not null default 0,
  review_count integer not null default 0,
  booking_count integer not null default 0,
  created_at timestamptz not null default now(),
  submitted_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by uuid references public.profiles (id)
);

create index studios_public_idx on public.studios (status, is_active);
create index studios_owner_idx on public.studios (owner_id);
create index studios_city_idx on public.studios ((address ->> 'city'));

-- Audit trail of moderation decisions.
create table public.studio_status_events (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid not null references public.studios (id) on delete cascade,
  from_status public.studio_status,
  to_status public.studio_status not null,
  note text,
  actor_id uuid references public.profiles (id),
  created_at timestamptz not null default now()
);

create table public.studio_payout_accounts (
  studio_id uuid primary key references public.studios (id) on delete cascade,
  account_holder text not null default '',
  iban_last4 text not null default '',
  stripe_account_id text,
  payouts_enabled boolean not null default false,
  updated_at timestamptz not null default now()
);

create table public.blocked_slots (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid not null references public.studios (id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  reason text not null default '',
  check (ends_at > starts_at)
);
create index blocked_slots_studio_idx on public.blocked_slots (studio_id, starts_at);

-- ---------------------------------------------------------------------------
-- Bookings & money
-- ---------------------------------------------------------------------------
create table public.bookings (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique,
  artist_id uuid not null references public.profiles (id),
  studio_id uuid not null references public.studios (id),
  artist_name text not null,
  studio_name text not null,
  session_type_id text not null,
  session_type_name text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  hours integer not null check (hours between 1 and 24),
  add_ons jsonb not null default '[]'::jsonb,
  status public.booking_status not null default 'awaiting_payment',
  payment_status public.payment_status not null default 'unpaid',
  price jsonb not null,
  notes text not null default '',
  cancellation_reason text,
  cancelled_by public.user_role,
  refund_amount integer not null default 0,
  has_review boolean not null default false,
  payment_intent_id text,
  balance_payment_intent_id text,
  payment_method public.payment_method,
  -- Who made the last change (set by edge functions) so triggers notify the other party.
  changed_by uuid,
  -- Cash bookings: set when the studio confirms it received the money.
  cash_received_at timestamptz,
  reminder_24h_sent_at timestamptz,
  reminder_2h_sent_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_at > starts_at),
  -- The database itself guarantees no double bookings.
  constraint bookings_no_overlap exclude using gist (
    studio_id with =,
    tstzrange(starts_at, ends_at, '[)') with &&
  ) where (status in ('awaiting_payment', 'pending_approval', 'confirmed'))
);
create index bookings_artist_idx on public.bookings (artist_id, starts_at desc);
create index bookings_studio_idx on public.bookings (studio_id, starts_at desc);
create index bookings_status_idx on public.bookings (status, starts_at);

create table public.transactions (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings (id),
  studio_id uuid not null references public.studios (id),
  artist_id uuid not null references public.profiles (id),
  kind public.transaction_kind not null,
  method public.payment_method not null default 'card',
  status public.transaction_status not null default 'pending',
  amount integer not null check (amount >= 0),
  platform_fee integer not null default 0,
  currency text not null,
  receipt_number text not null unique default ('RCPT-' || upper(substr(md5(gen_random_uuid()::text), 1, 10))),
  card_brand text,
  card_last4 text,
  failure_reason text,
  provider_reference text,
  created_at timestamptz not null default now()
);
create index transactions_booking_idx on public.transactions (booking_id);
create unique index transactions_provider_ref_idx on public.transactions (provider_reference, kind);

create table public.payouts (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid not null references public.studios (id),
  amount integer not null,
  currency text not null,
  status public.payout_status not null default 'scheduled',
  scheduled_for timestamptz not null,
  paid_at timestamptz,
  booking_ids uuid[] not null default '{}',
  provider_reference text,
  failure_reason text,
  created_at timestamptz not null default now()
);
create index payouts_studio_idx on public.payouts (studio_id, scheduled_for desc);

create table public.disputes (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings (id),
  opened_by uuid not null references public.profiles (id),
  reason text not null,
  status public.report_status not null default 'open',
  resolution text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);

-- ---------------------------------------------------------------------------
-- Communication
-- ---------------------------------------------------------------------------
create table public.conversations (
  id uuid primary key default gen_random_uuid(),
  artist_id uuid not null references public.profiles (id) on delete cascade,
  studio_id uuid not null references public.studios (id) on delete cascade,
  booking_id uuid references public.bookings (id) on delete set null,
  artist_name text not null,
  studio_name text not null,
  studio_photo_url text,
  last_message_preview text not null default '',
  last_message_at timestamptz not null default now(),
  artist_unread integer not null default 0,
  studio_unread integer not null default 0,
  created_at timestamptz not null default now()
);
-- One thread per artist+studio(+booking). Chat is always scoped; there is no free social messaging.
create unique index conversations_scope_idx on public.conversations (artist_id, studio_id, coalesce(booking_id, '00000000-0000-0000-0000-000000000000'::uuid));

create table public.messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations (id) on delete cascade,
  sender_id uuid references public.profiles (id) on delete set null,
  kind public.message_kind not null default 'text',
  body text not null check (char_length(body) between 1 and 2000),
  created_at timestamptz not null default now()
);
create index messages_conversation_idx on public.messages (conversation_id, created_at);

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind public.notification_kind not null,
  title text not null,
  body text not null,
  is_read boolean not null default false,
  booking_id uuid references public.bookings (id) on delete set null,
  conversation_id uuid references public.conversations (id) on delete set null,
  studio_id uuid references public.studios (id) on delete set null,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Reviews & moderation
-- ---------------------------------------------------------------------------
create table public.reviews (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.bookings (id),
  studio_id uuid not null references public.studios (id) on delete cascade,
  artist_id uuid not null references public.profiles (id) on delete cascade,
  artist_name text not null,
  rating integer not null check (rating between 1 and 5),
  facilities_rating integer not null check (facilities_rating between 1 and 5),
  experience_rating integer not null check (experience_rating between 1 and 5),
  engineer_rating integer check (engineer_rating between 1 and 5),
  text text not null default '',
  studio_reply text,
  studio_replied_at timestamptz,
  is_hidden boolean not null default false,
  created_at timestamptz not null default now()
);
create index reviews_studio_idx on public.reviews (studio_id, created_at desc);

create table public.reports (
  id uuid primary key default gen_random_uuid(),
  reporter_id uuid not null references public.profiles (id) on delete cascade,
  target_type public.report_target not null,
  target_id uuid not null,
  reason public.report_reason not null,
  details text not null default '',
  status public.report_status not null default 'open',
  admin_note text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);
create index reports_status_idx on public.reports (status, created_at desc);

-- Commercial settings (mirrored in supabase/functions/_shared/pricing.ts).
create table public.platform_settings (
  key text primary key,
  value jsonb not null
);
insert into public.platform_settings (key, value) values
  -- EasySesh takes 10% of every sale. Card payments: deducted from the studio payout.
  -- Cash payments: owed by the studio (see studio_fee_ledger).
  ('artist_service_fee_percent', '0'),
  ('platform_fee_percent', '10'),
  ('payout_delay_days', '2');

-- ---------------------------------------------------------------------
-- 20260924000002_security.sql
-- ---------------------------------------------------------------------
-- EasySesh: identity helpers, sign-up hook, column guards and row-level security.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin' and status = 'active'
  )
  -- Admins must have signed in with a second factor (TOTP).
  and coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2';
$$;

-- Studio features (calendar blocks, replies, studio-side chat, payouts) require an approved studio.
-- Signing up as a studio – or being an artist – never grants them on its own.
create or replace function public.owns_approved_studio(p_studio_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.studios s join public.profiles p on p.id = s.owner_id
    where s.id = p_studio_id and s.owner_id = auth.uid() and s.status = 'approved'
      and p.role = 'studio_owner' and p.status = 'active'
  );
$$;

-- True for the service role, SECURITY DEFINER functions (run as the table owner) and admins.
-- Deliberately SECURITY INVOKER so current_user reflects the real caller.
create or replace function public.is_trusted()
returns boolean
language sql stable
as $$
  select current_user not in ('authenticated', 'anon') or public.is_admin();
$$;

create or replace function public.is_active_user()
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.profiles where id = auth.uid() and status = 'active');
$$;

create or replace function public.owns_studio(p_studio_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from public.studios where id = p_studio_id and owner_id = auth.uid());
$$;

create or replace function public.is_conversation_participant(p_conversation_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.conversations c
    join public.studios s on s.id = c.studio_id
    where c.id = p_conversation_id and (c.artist_id = auth.uid() or s.owner_id = auth.uid())
  );
$$;

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Sign-up: create the profile row (role comes from sign-up metadata; admins are never self-assigned)
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  requested text := coalesce(new.raw_user_meta_data ->> 'role', 'artist');
  assigned public.user_role := case when requested = 'studio_owner' then 'studio_owner'::public.user_role else 'artist'::public.user_role end;
begin
  insert into public.profiles (id, email, role, accepted_terms_version, accepted_terms_at)
  values (
    new.id, coalesce(new.email, ''), assigned,
    new.raw_user_meta_data ->> 'terms_version',
    case when new.raw_user_meta_data ? 'terms_version' then now() end
  );
  if assigned = 'artist' then
    insert into public.artist_profiles (id, artist_name)
    values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name', ''));
  end if;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Apple/Google sign-up can't pass metadata; a brand-new account may switch to studio owner once.
create or replace function public.claim_role(p_role public.user_role)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  me public.profiles;
begin
  select * into me from public.profiles where id = auth.uid();
  if me.id is null then raise exception 'not_found'; end if;
  if p_role = 'admin' then raise exception 'forbidden'; end if;
  if me.role = p_role then return; end if;
  if me.created_at < now() - interval '1 hour'
     or exists (select 1 from public.bookings where artist_id = me.id)
     or exists (select 1 from public.conversations where artist_id = me.id)
     or exists (select 1 from public.studios where owner_id = me.id) then
    raise exception 'This account already has a role. Contact support to change it.';
  end if;
  update public.profiles set role = p_role where id = me.id;
  if p_role = 'studio_owner' then
    delete from public.artist_profiles where id = me.id;
  else
    insert into public.artist_profiles (id) values (me.id) on conflict do nothing;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Column guards: users may edit their content, never moderation/financial fields.
-- ---------------------------------------------------------------------------
create or replace function public.guard_profiles()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    new.id := old.id;
    new.email := old.email;
    new.role := old.role;
    new.status := old.status;
    new.status_reason := old.status_reason;
    new.is_verified := old.is_verified;
    new.stripe_customer_id := old.stripe_customer_id;
    new.accepted_terms_version := old.accepted_terms_version;
    new.accepted_terms_at := old.accepted_terms_at;
    new.created_at := old.created_at;
  end if;
  return new;
end;
$$;
create trigger guard_profiles before update on public.profiles
  for each row execute function public.guard_profiles();

create or replace function public.guard_artist_profiles()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    if tg_op = 'INSERT' then
      new.is_verified := false;
    else
      new.is_verified := old.is_verified;
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;
create trigger guard_artist_profiles before insert or update on public.artist_profiles
  for each row execute function public.guard_artist_profiles();

create or replace function public.guard_studios()
returns trigger language plpgsql as $$
begin
  -- Keep the "from" price in sync with the session types.
  new.price_from := coalesce((select min((t.value ->> 'hourly_rate')::int) from jsonb_array_elements(new.session_types) as t), 0);

  if public.is_trusted() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    -- Upsert of an existing row: Postgres runs this INSERT trigger before resolving the conflict.
    -- The UPDATE branch below guards the row that actually gets written, so leave it alone here.
    if exists (select 1 from public.studios where id = new.id) then
      return new;
    end if;
    if new.owner_id is distinct from auth.uid()
       or not exists (select 1 from public.profiles where id = auth.uid() and role = 'studio_owner' and status = 'active') then
      raise exception 'forbidden' using errcode = '42501';
    end if;
    if exists (select 1 from public.studios where owner_id = auth.uid() and id <> new.id) then
      raise exception 'You already have a studio.';
    end if;
    new.status := 'draft';
    new.is_active := false;
    new.is_verified := false;
    new.admin_note := null;
    new.rating_average := 0;
    new.review_count := 0;
    new.booking_count := 0;
    new.submitted_at := null;
    new.reviewed_at := null;
    new.reviewed_by := null;
    new.created_at := now();
  else
    new.id := old.id;
    new.owner_id := old.owner_id;
    new.status := old.status;
    new.is_verified := old.is_verified;
    new.admin_note := old.admin_note;
    new.rating_average := old.rating_average;
    new.review_count := old.review_count;
    new.booking_count := old.booking_count;
    new.submitted_at := old.submitted_at;
    new.reviewed_at := old.reviewed_at;
    new.reviewed_by := old.reviewed_by;
    new.created_at := old.created_at;
    -- Going live/paused only happens through set_studio_active (or an admin), never through a
    -- listing save, so a stale copy in the app can't hide an approved studio.
    new.is_active := old.is_active;
    if new.status <> 'approved' then
      new.is_active := false;
    end if;
  end if;
  return new;
end;
$$;
create trigger guard_studios before insert or update on public.studios
  for each row execute function public.guard_studios();

create or replace function public.guard_notifications()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    -- Only the read flag may change.
    new := old;
    new.is_read := true;
  end if;
  return new;
end;
$$;
create trigger guard_notifications before update on public.notifications
  for each row execute function public.guard_notifications();

create trigger bookings_touch before update on public.bookings
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.artist_profiles enable row level security;
alter table public.device_tokens enable row level security;
alter table public.studios enable row level security;
alter table public.studio_status_events enable row level security;
alter table public.studio_payout_accounts enable row level security;
alter table public.blocked_slots enable row level security;
alter table public.bookings enable row level security;
alter table public.transactions enable row level security;
alter table public.payouts enable row level security;
alter table public.disputes enable row level security;
alter table public.conversations enable row level security;
alter table public.messages enable row level security;
alter table public.notifications enable row level security;
alter table public.reviews enable row level security;
alter table public.reports enable row level security;
alter table public.platform_settings enable row level security;

-- profiles
create policy "profiles: read own" on public.profiles for select using (id = auth.uid() or public.is_admin());
create policy "profiles: update own" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());

-- artist_profiles are public to signed-in users (studios see who books them)
create policy "artist_profiles: read" on public.artist_profiles for select to authenticated using (true);
create policy "artist_profiles: insert own" on public.artist_profiles for insert with check (id = auth.uid());
create policy "artist_profiles: update own" on public.artist_profiles for update using (id = auth.uid()) with check (id = auth.uid());

-- device tokens
create policy "device_tokens: own" on public.device_tokens for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- studios: approved+active are public; owners see their own; admins see all
create policy "studios: read public" on public.studios for select
  using ((status = 'approved' and is_active) or owner_id = auth.uid() or public.is_admin()
         or exists (select 1 from public.bookings b where b.studio_id = studios.id and b.artist_id = auth.uid()));
create policy "studios: owner insert" on public.studios for insert with check (owner_id = auth.uid());
create policy "studios: owner update" on public.studios for update using (owner_id = auth.uid() or public.is_admin()) with check (owner_id = auth.uid() or public.is_admin());

create policy "studio_status_events: read" on public.studio_status_events for select
  using (public.owns_studio(studio_id) or public.is_admin());

create policy "payout_accounts: owner read" on public.studio_payout_accounts for select
  using (public.owns_studio(studio_id) or public.is_admin());

create policy "blocked_slots: owner read" on public.blocked_slots for select
  using (public.owns_studio(studio_id));
create policy "blocked_slots: approved owner write" on public.blocked_slots for insert
  with check (public.owns_approved_studio(studio_id));
create policy "blocked_slots: approved owner delete" on public.blocked_slots for delete
  using (public.owns_approved_studio(studio_id));

-- bookings & money: read-only for participants; all writes go through edge functions / RPCs
create policy "bookings: participants read" on public.bookings for select
  using (artist_id = auth.uid() or public.owns_studio(studio_id) or public.is_admin());
create policy "transactions: participants read" on public.transactions for select
  using (artist_id = auth.uid() or public.owns_studio(studio_id) or public.is_admin());
create policy "payouts: owner read" on public.payouts for select
  using (public.owns_studio(studio_id) or public.is_admin());
create policy "disputes: participants read" on public.disputes for select
  using (opened_by = auth.uid() or public.is_admin()
         or exists (select 1 from public.bookings b where b.id = booking_id and (b.artist_id = auth.uid() or public.owns_studio(b.studio_id))));

-- chat
create policy "conversations: participants read" on public.conversations for select
  using (artist_id = auth.uid() or public.owns_studio(studio_id) or public.is_admin());
create policy "messages: participants read" on public.messages for select
  using (public.is_conversation_participant(conversation_id) or public.is_admin());
-- Artists can write in their own threads; the studio side only once the studio is approved.
create policy "messages: participants send" on public.messages for insert
  with check (
    sender_id = auth.uid() and kind = 'text' and public.is_active_user()
    and exists (
      select 1 from public.conversations c
      where c.id = conversation_id
        and (c.artist_id = auth.uid() or public.owns_approved_studio(c.studio_id))
    )
  );

-- notifications
create policy "notifications: own read" on public.notifications for select using (user_id = auth.uid());
create policy "notifications: own mark read" on public.notifications for update using (user_id = auth.uid()) with check (user_id = auth.uid());

-- reviews: public; artists write one per completed booking; replies via RPC
create policy "reviews: read" on public.reviews for select using (not is_hidden or artist_id = auth.uid() or public.owns_studio(studio_id) or public.is_admin());
create policy "reviews: artist insert" on public.reviews for insert with check (
  artist_id = auth.uid()
  and exists (
    select 1 from public.bookings b
    where b.id = booking_id and b.artist_id = auth.uid() and b.studio_id = reviews.studio_id
      and b.status = 'completed' and not b.has_review
  )
);

-- reports
create policy "reports: insert own" on public.reports for insert with check (reporter_id = auth.uid());
create policy "reports: read own or admin" on public.reports for select using (reporter_id = auth.uid() or public.is_admin());

create policy "platform_settings: read" on public.platform_settings for select using (true);

-- ---------------------------------------------------------------------------
-- Storage: public "media" bucket; users write only under their own user-id prefix.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public) values ('media', 'media', true) on conflict (id) do nothing;

create policy "media: upload own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "media: update own folder" on storage.objects for update to authenticated
  using (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "media: delete own folder" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and (storage.foldername(name))[1] = auth.uid()::text);

-- ---------------------------------------------------------------------
-- 20260924000003_app_logic.sql
-- ---------------------------------------------------------------------
-- EasySesh: RPCs used by the app and triggers that keep derived data + notifications in sync.

-- ---------------------------------------------------------------------------
-- Notifications helper
-- ---------------------------------------------------------------------------
create or replace function public.notify(
  p_user_id uuid,
  p_kind public.notification_kind,
  p_title text,
  p_body text,
  p_booking_id uuid default null,
  p_conversation_id uuid default null,
  p_studio_id uuid default null
) returns void
language sql security definer set search_path = public
as $$
  insert into public.notifications (user_id, kind, title, body, booking_id, conversation_id, studio_id)
  select p_user_id, p_kind, p_title, p_body, p_booking_id, p_conversation_id, p_studio_id
  where p_user_id is not null;
$$;
revoke execute on function public.notify from public, anon, authenticated;

create or replace function public.format_local(p_at timestamptz, p_studio_id uuid)
returns text language sql stable security definer set search_path = public
as $$
  select to_char(p_at at time zone coalesce((select timezone from public.studios where id = p_studio_id), 'UTC'), 'Dy DD Mon, HH24:MI');
$$;

create or replace function public.format_money(p_amount integer, p_currency text)
returns text language sql immutable
as $$
  select p_currency || ' ' || to_char(p_amount / 100.0, 'FM999999990.00');
$$;

-- Adds a system line to every conversation tied to a booking.
create or replace function public.booking_system_message(p_booking_id uuid, p_body text)
returns void
language sql security definer set search_path = public
as $$
  insert into public.messages (conversation_id, sender_id, kind, body)
  select id, null, 'system', p_body from public.conversations where booking_id = p_booking_id;
$$;
revoke execute on function public.booking_system_message from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Studios
-- ---------------------------------------------------------------------------
create or replace function public.studio_validation_problems(s public.studios)
returns text[]
language plpgsql stable
as $$
declare
  problems text[] := '{}';
begin
  if char_length(trim(s.name)) < 3 then problems := array_append(problems, 'Add your studio''s name.'::text); end if;
  if char_length(s.description) < 40 then problems := array_append(problems, 'Write a description of at least 40 characters.'::text); end if;
  if cardinality(s.photo_urls) = 0 then problems := array_append(problems, 'Add at least one photo.'::text); end if;
  if coalesce(s.address ->> 'street', '') = '' or coalesce(s.address ->> 'city', '') = '' then problems := array_append(problems, 'Add the studio''s address.'::text); end if;
  if s.latitude = 0 and s.longitude = 0 then problems := array_append(problems, 'Place your studio on the map.'::text); end if;
  if coalesce(s.contact ->> 'email', '') = '' and coalesce(s.contact ->> 'phone', '') = '' then problems := array_append(problems, 'Add an email or phone number.'::text); end if;
  if jsonb_array_length(s.session_types) = 0 or exists (
       select 1 from jsonb_array_elements(s.session_types) as t where coalesce((t.value ->> 'hourly_rate')::int, 0) <= 0) then
    problems := array_append(problems, 'Set a price for each session type.'::text);
  end if;
  if not exists (select 1 from jsonb_array_elements(s.opening_hours) as h where not coalesce((h.value ->> 'is_closed')::boolean, false)) then
    problems := array_append(problems, 'Set your opening hours.'::text);
  end if;
  if cardinality(s.genres) = 0 then problems := array_append(problems, 'Pick at least one genre.'::text); end if;
  return problems;
end;
$$;

create or replace function public.submit_studio_for_review(p_studio_id uuid)
returns public.studios
language plpgsql security definer set search_path = public
as $$
declare
  s public.studios;
  problems text[];
begin
  select * into s from public.studios where id = p_studio_id and owner_id = auth.uid() for update;
  if s.id is null then raise exception 'not_found'; end if;
  if s.status not in ('draft', 'changes_requested', 'rejected') then return s; end if;
  problems := public.studio_validation_problems(s);
  if cardinality(problems) > 0 then raise exception '%', problems[1]; end if;

  insert into public.studio_status_events (studio_id, from_status, to_status, actor_id)
  values (s.id, s.status, 'pending_review', auth.uid());
  update public.studios set status = 'pending_review', submitted_at = now() where id = s.id returning * into s;
  return s;
end;
$$;

create or replace function public.set_studio_active(p_studio_id uuid, p_active boolean)
returns public.studios
language plpgsql security definer set search_path = public
as $$
declare
  s public.studios;
begin
  select * into s from public.studios where id = p_studio_id and owner_id = auth.uid();
  if s.id is null then raise exception 'not_found'; end if;
  if s.status <> 'approved' then raise exception 'Your studio must be approved before it can go live.'; end if;
  update public.studios set is_active = p_active where id = s.id returning * into s;
  return s;
end;
$$;

-- Occupied time ranges for availability. Exposes no personal data.
create or replace function public.studio_busy_intervals(p_studio_ids uuid[], p_from timestamptz, p_to timestamptz)
returns table (studio_id uuid, starts_at timestamptz, ends_at timestamptz)
language sql stable security definer set search_path = public
as $$
  select b.studio_id, b.starts_at, b.ends_at from public.bookings b
  where b.studio_id = any (p_studio_ids)
    and b.status in ('awaiting_payment', 'pending_approval', 'confirmed')
    and b.starts_at < p_to and b.ends_at > p_from
  union all
  select s.studio_id, s.starts_at, s.ends_at from public.blocked_slots s
  where s.studio_id = any (p_studio_ids) and s.starts_at < p_to and s.ends_at > p_from;
$$;

create or replace function public.on_studio_status_change()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if new.status is distinct from old.status then
    if new.status = 'approved' then
      perform public.notify(new.owner_id, 'studio_approved', 'Your studio is live', new.name || ' was approved and is now visible to artists.', null, null, new.id);
    elsif new.status = 'rejected' then
      perform public.notify(new.owner_id, 'studio_rejected', 'Application not approved', coalesce(new.admin_note, 'Your studio was not approved.'), null, null, new.id);
    elsif new.status = 'changes_requested' then
      perform public.notify(new.owner_id, 'studio_changes_requested', 'Changes requested', coalesce(new.admin_note, 'Please update your listing and resubmit.'), null, null, new.id);
    elsif new.status = 'suspended' then
      perform public.notify(new.owner_id, 'system', 'Studio suspended', coalesce(new.admin_note, 'Your studio has been suspended. Contact support.'), null, null, new.id);
    end if;
  end if;
  return new;
end;
$$;
create trigger on_studio_status_change after update of status on public.studios
  for each row execute function public.on_studio_status_change();

-- ---------------------------------------------------------------------------
-- Bookings → notifications, system messages, counters
-- ---------------------------------------------------------------------------
create or replace function public.on_booking_change()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  owner uuid;
  when_text text;
begin
  select owner_id into owner from public.studios where id = new.studio_id;
  when_text := public.format_local(new.starts_at, new.studio_id);

  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    case new.status
      when 'pending_approval' then
        perform public.notify(owner, 'booking_requested', 'New booking request',
          new.artist_name || ' wants to book ' || new.hours || 'h on ' || when_text || '. Accept or decline.', new.id);
      when 'confirmed' then
        perform public.notify(new.artist_id, 'booking_confirmed', 'Booking confirmed', new.studio_name || ' · ' || when_text, new.id);
        if old.status = 'awaiting_payment' then
          perform public.notify(owner, 'booking_requested', 'New booking', new.artist_name || ' booked ' || new.hours || 'h on ' || when_text || '.', new.id);
        end if;
        update public.studios set booking_count = booking_count + 1 where id = new.studio_id;
      when 'declined' then
        perform public.notify(new.artist_id, 'booking_declined', 'Request declined',
          new.studio_name || ' couldn''t take your session. Your card was not charged.' || coalesce(' “' || new.cancellation_reason || '”', ''), new.id);
      when 'cancelled' then
        if new.cancelled_by = 'artist' then
          perform public.notify(owner, 'booking_cancelled', 'Booking cancelled', new.artist_name || ' cancelled the session on ' || when_text || '.', new.id);
        else
          perform public.notify(new.artist_id, 'booking_cancelled', 'Booking cancelled by studio',
            new.studio_name || ' cancelled your session on ' || when_text || '. You''ll get a full refund.', new.id);
        end if;
        perform public.booking_system_message(new.id, 'Booking ' || new.reference || ' was cancelled by the ' || case when new.cancelled_by = 'artist' then 'artist' else 'studio' end || '.');
      when 'completed' then
        perform public.notify(new.artist_id, 'review_reminder', 'How was ' || new.studio_name || '?', 'Leave a review for your session.', new.id, null, new.studio_id);
      when 'disputed' then
        perform public.notify(owner, 'system', 'Problem reported', 'A problem was reported on booking ' || new.reference || '. Our team will contact you.', new.id);
      else
        null;
    end case;
  end if;

  if tg_op = 'UPDATE' and new.starts_at is distinct from old.starts_at and new.status = 'confirmed' then
    perform public.notify(case when new.changed_by = new.artist_id then owner else new.artist_id end, 'booking_changed', 'Booking moved',
      new.reference || ' moved from ' || public.format_local(old.starts_at, new.studio_id) || ' to ' || when_text || '.', new.id);
    perform public.booking_system_message(new.id, 'Booking moved from ' || public.format_local(old.starts_at, new.studio_id) || ' to ' || when_text || '.');
  end if;

  if tg_op = 'UPDATE' and new.refund_amount > old.refund_amount and new.payment_status in ('refunded', 'partially_refunded') and old.payment_status <> 'authorized' then
    perform public.notify(new.artist_id, 'refund_issued', 'Refund on its way',
      public.format_money(new.refund_amount - old.refund_amount, new.price ->> 'currency') || ' will be back on your card in 5–10 days.', new.id);
  end if;

  return new;
end;
$$;
create trigger on_booking_change after update on public.bookings
  for each row execute function public.on_booking_change();

create or replace function public.open_dispute(p_booking_id uuid, p_reason text)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  b public.bookings;
begin
  select * into b from public.bookings where id = p_booking_id;
  if b.id is null then raise exception 'not_found'; end if;
  if b.artist_id <> auth.uid() and not public.owns_studio(b.studio_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if b.status not in ('confirmed', 'completed') then raise exception 'You can only report a problem on a confirmed or completed booking.'; end if;
  insert into public.disputes (booking_id, opened_by, reason) values (b.id, auth.uid(), p_reason);
  update public.bookings set status = 'disputed', changed_by = auth.uid() where id = b.id;
  perform public.notify(auth.uid(), 'system', 'We''re on it', 'Our team will review booking ' || b.reference || ' within 24 hours.', b.id);
end;
$$;

-- ---------------------------------------------------------------------------
-- Chat
-- ---------------------------------------------------------------------------
create or replace function public.get_or_create_conversation(p_studio_id uuid, p_booking_id uuid default null)
returns public.conversations
language plpgsql security definer set search_path = public
as $$
declare
  me public.profiles;
  s public.studios;
  b public.bookings;
  artist uuid;
  convo public.conversations;
begin
  select * into me from public.profiles where id = auth.uid();
  if me.id is null or me.status <> 'active' then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into s from public.studios where id = p_studio_id;
  if s.id is null then raise exception 'not_found'; end if;

  if p_booking_id is not null then
    select * into b from public.bookings where id = p_booking_id and studio_id = p_studio_id;
    if b.id is null then raise exception 'not_found'; end if;
  end if;

  if me.role = 'artist' then
    if p_booking_id is null and not (s.status = 'approved' and s.is_active) then raise exception 'not_found'; end if;
    if b.id is not null and b.artist_id <> me.id then raise exception 'forbidden' using errcode = '42501'; end if;
    artist := me.id;
  elsif s.owner_id = me.id and b.id is not null and public.owns_approved_studio(s.id) then
    -- Studios can only start a conversation about one of their bookings.
    artist := b.artist_id;
  else
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select * into convo from public.conversations
  where artist_id = artist and studio_id = s.id and booking_id is not distinct from p_booking_id;
  if convo.id is not null then return convo; end if;

  insert into public.conversations (artist_id, studio_id, booking_id, artist_name, studio_name, studio_photo_url)
  values (
    artist, s.id, p_booking_id,
    coalesce(nullif((select artist_name from public.artist_profiles where id = artist), ''), 'Artist'),
    s.name, s.photo_urls[1]
  )
  returning * into convo;
  return convo;
end;
$$;

create or replace function public.mark_conversation_read(p_conversation_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  update public.conversations c set
    artist_unread = case when c.artist_id = auth.uid() then 0 else c.artist_unread end,
    studio_unread = case when public.owns_studio(c.studio_id) then 0 else c.studio_unread end
  where c.id = p_conversation_id;
end;
$$;

create or replace function public.on_message_insert()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  c public.conversations;
  owner uuid;
  from_artist boolean;
begin
  select * into c from public.conversations where id = new.conversation_id;
  select owner_id into owner from public.studios where id = c.studio_id;
  from_artist := new.sender_id = c.artist_id;

  update public.conversations set
    last_message_preview = left(new.body, 140),
    last_message_at = new.created_at,
    artist_unread = artist_unread + case when new.sender_id is null or not from_artist then 1 else 0 end,
    studio_unread = studio_unread + case when new.sender_id is null or from_artist then 1 else 0 end
  where id = c.id;

  if new.kind = 'text' then
    perform public.notify(
      case when from_artist then owner else c.artist_id end,
      'new_message',
      case when from_artist then c.artist_name else c.studio_name end,
      left(new.body, 140),
      c.booking_id, c.id
    );
  end if;
  return new;
end;
$$;
create trigger on_message_insert after insert on public.messages
  for each row execute function public.on_message_insert();

-- ---------------------------------------------------------------------------
-- Reviews
-- ---------------------------------------------------------------------------
-- SECURITY INVOKER on purpose: is_trusted() must see the real caller.
create or replace function public.before_review_insert()
returns trigger
language plpgsql
as $$
begin
  new.artist_name := coalesce(nullif((select artist_name from public.artist_profiles where id = new.artist_id), ''), new.artist_name);
  if not public.is_trusted() then
    new.studio_reply := null;
    new.studio_replied_at := null;
    new.is_hidden := false;
    new.created_at := now();
  end if;
  return new;
end;
$$;
create trigger before_review_insert before insert on public.reviews
  for each row execute function public.before_review_insert();

create or replace function public.refresh_studio_rating(p_studio_id uuid)
returns void
language sql security definer set search_path = public
as $$
  update public.studios s set
    rating_average = coalesce((select round(avg(rating)::numeric, 1) from public.reviews r where r.studio_id = s.id and not r.is_hidden), 0),
    review_count = (select count(*) from public.reviews r where r.studio_id = s.id and not r.is_hidden)
  where s.id = p_studio_id;
$$;

create or replace function public.after_review_change()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  owner uuid;
begin
  perform public.refresh_studio_rating(new.studio_id);
  if tg_op = 'INSERT' then
    update public.bookings set has_review = true where id = new.booking_id;
    select owner_id into owner from public.studios where id = new.studio_id;
    perform public.notify(owner, 'new_review', 'New ' || new.rating || '★ review',
      new.artist_name || ' reviewed your studio.', new.booking_id, null, new.studio_id);
  end if;
  return new;
end;
$$;
create trigger after_review_insert after insert on public.reviews
  for each row execute function public.after_review_change();
create trigger after_review_visibility after update of is_hidden on public.reviews
  for each row execute function public.after_review_change();

create or replace function public.reply_to_review(p_review_id uuid, p_reply text)
returns public.reviews
language plpgsql security definer set search_path = public
as $$
declare
  r public.reviews;
begin
  select * into r from public.reviews where id = p_review_id;
  if r.id is null then raise exception 'not_found'; end if;
  if not public.owns_approved_studio(r.studio_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(trim(p_reply)) = 0 then raise exception 'Write a reply first.'; end if;
  update public.reviews set studio_reply = trim(p_reply), studio_replied_at = now() where id = r.id returning * into r;
  return r;
end;
$$;

-- ---------------------------------------------------------------------------
-- Payouts
-- ---------------------------------------------------------------------------
create or replace function public.on_payout_paid()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  owner uuid;
begin
  if new.status = 'paid' and old.status is distinct from 'paid' then
    select owner_id into owner from public.studios where id = new.studio_id;
    perform public.notify(owner, 'payout_sent', 'Payout sent', public.format_money(new.amount, new.currency) || ' is on its way to your bank.', null, null, new.studio_id);
  end if;
  return new;
end;
$$;
create trigger on_payout_paid after update of status on public.payouts
  for each row execute function public.on_payout_paid();

-- ---------------------------------------------------------------------------
-- Realtime: stream chat messages and notifications to the app.
-- ---------------------------------------------------------------------------
alter publication supabase_realtime add table public.messages, public.notifications;

-- Called by edge functions when an automatic balance charge fails.
create or replace function public.notify_payment_problem(p_booking_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  b public.bookings;
begin
  select * into b from public.bookings where id = p_booking_id;
  perform public.notify(b.artist_id, 'system', 'Payment problem',
    'We couldn''t charge the remaining ' || public.format_money((b.price ->> 'due_later')::int, b.price ->> 'currency')
    || ' for booking ' || b.reference || '. Please update your card or contact support.', b.id);
end;
$$;
revoke execute on function public.notify_payment_problem from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- 20260924000004_admin.sql
-- ---------------------------------------------------------------------
-- EasySesh: admin dashboard RPCs. Every function checks public.is_admin().

create or replace function public.require_admin()
returns void
language plpgsql stable security definer set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
end;
$$;

-- approve | reject | request_changes
create or replace function public.admin_review_studio(p_studio_id uuid, p_decision text, p_note text default null)
returns public.studios
language plpgsql security definer set search_path = public
as $$
declare
  s public.studios;
  previous public.studio_status;
  next_status public.studio_status;
begin
  perform public.require_admin();
  select * into s from public.studios where id = p_studio_id for update;
  if s.id is null then raise exception 'not_found'; end if;
  previous := s.status;

  next_status := case p_decision
    when 'approve' then 'approved'::public.studio_status
    when 'reject' then 'rejected'::public.studio_status
    when 'request_changes' then 'changes_requested'::public.studio_status
  end;
  if next_status is null then raise exception 'Unknown decision %', p_decision; end if;
  if next_status <> 'approved' and coalesce(trim(p_note), '') = '' then
    raise exception 'Add a note explaining what the studio should change.';
  end if;

  update public.studios set
    status = next_status,
    is_active = (next_status = 'approved'),
    is_verified = case when next_status = 'approved' then true else is_verified end,
    admin_note = p_note,
    reviewed_at = now(),
    reviewed_by = auth.uid()
  where id = s.id
  returning * into s;

  insert into public.studio_status_events (studio_id, from_status, to_status, note, actor_id)
  values (s.id, previous, next_status, p_note, auth.uid());
  return s;
end;
$$;

create or replace function public.admin_set_studio_state(p_studio_id uuid, p_active boolean default null, p_verified boolean default null, p_suspended boolean default null, p_note text default null)
returns public.studios
language plpgsql security definer set search_path = public
as $$
declare
  s public.studios;
begin
  perform public.require_admin();
  select * into s from public.studios where id = p_studio_id for update;
  if s.id is null then raise exception 'not_found'; end if;

  if p_suspended is true and s.status <> 'suspended' then
    update public.studios set status = 'suspended', is_active = false, admin_note = coalesce(p_note, admin_note) where id = s.id;
    insert into public.studio_status_events (studio_id, from_status, to_status, note, actor_id) values (s.id, s.status, 'suspended', p_note, auth.uid());
  elsif p_suspended is false and s.status = 'suspended' then
    update public.studios set status = 'approved', admin_note = coalesce(p_note, admin_note) where id = s.id;
    insert into public.studio_status_events (studio_id, from_status, to_status, note, actor_id) values (s.id, 'suspended', 'approved', p_note, auth.uid());
  end if;
  if p_active is not null then
    update public.studios set is_active = p_active and status = 'approved' where id = s.id;
  end if;
  if p_verified is not null then
    update public.studios set is_verified = p_verified where id = s.id;
  end if;
  select * into s from public.studios where id = p_studio_id;
  return s;
end;
$$;

-- active | suspended | banned. Suspending a studio owner also hides their studio.
create or replace function public.admin_set_user_status(p_user_id uuid, p_status public.account_status, p_reason text default null)
returns public.profiles
language plpgsql security definer set search_path = public
as $$
declare
  p public.profiles;
begin
  perform public.require_admin();
  if p_user_id = auth.uid() then raise exception 'You cannot change your own status.'; end if;
  update public.profiles set status = p_status, status_reason = p_reason where id = p_user_id returning * into p;
  if p.id is null then raise exception 'not_found'; end if;
  if p_status <> 'active' then
    update public.studios set is_active = false where owner_id = p_user_id;
    delete from public.device_tokens where user_id = p_user_id;
  end if;
  return p;
end;
$$;

create or replace function public.admin_verify_user(p_user_id uuid, p_verified boolean)
returns public.profiles
language plpgsql security definer set search_path = public
as $$
declare
  p public.profiles;
begin
  perform public.require_admin();
  update public.profiles set is_verified = p_verified where id = p_user_id returning * into p;
  update public.artist_profiles set is_verified = p_verified where id = p_user_id;
  return p;
end;
$$;

create or replace function public.admin_resolve_report(p_report_id uuid, p_status public.report_status, p_note text default null)
returns public.reports
language plpgsql security definer set search_path = public
as $$
declare
  r public.reports;
begin
  perform public.require_admin();
  update public.reports set status = p_status, admin_note = p_note, resolved_at = case when p_status = 'open' then null else now() end
  where id = p_report_id returning * into r;
  return r;
end;
$$;

create or replace function public.admin_set_review_hidden(p_review_id uuid, p_hidden boolean)
returns public.reviews
language plpgsql security definer set search_path = public
as $$
declare
  r public.reviews;
begin
  perform public.require_admin();
  update public.reviews set is_hidden = p_hidden where id = p_review_id returning * into r;
  return r;
end;
$$;

-- Closes a dispute. Money movements (refunds) are done through the admin-refund edge function first.
create or replace function public.admin_resolve_dispute(p_dispute_id uuid, p_resolution text, p_booking_status public.booking_status default 'completed')
returns public.disputes
language plpgsql security definer set search_path = public
as $$
declare
  d public.disputes;
begin
  perform public.require_admin();
  update public.disputes set status = 'resolved', resolution = p_resolution, resolved_at = now() where id = p_dispute_id returning * into d;
  if d.id is null then raise exception 'not_found'; end if;
  update public.bookings set status = p_booking_status, changed_by = auth.uid() where id = d.booking_id and status = 'disputed';
  return d;
end;
$$;

-- Numbers for the admin overview. Revenue figures are in minor units per currency.
create or replace function public.admin_dashboard_stats(p_from timestamptz default now() - interval '30 days', p_to timestamptz default now())
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  result jsonb;
begin
  perform public.require_admin();
  select jsonb_build_object(
    'artists', (select count(*) from public.profiles where role = 'artist'),
    'studio_owners', (select count(*) from public.profiles where role = 'studio_owner'),
    'studios_live', (select count(*) from public.studios where status = 'approved' and is_active),
    'studios_pending', (select count(*) from public.studios where status = 'pending_review'),
    'bookings_total', (select count(*) from public.bookings where created_at between p_from and p_to and status <> 'awaiting_payment'),
    'bookings_confirmed', (select count(*) from public.bookings where created_at between p_from and p_to and status in ('confirmed', 'completed')),
    'bookings_cancelled', (select count(*) from public.bookings where created_at between p_from and p_to and status in ('cancelled', 'declined')),
    'booking_rate', (
      select case when count(*) = 0 then 0 else round(100.0 * count(*) filter (where status in ('confirmed', 'completed', 'disputed')) / count(*), 1) end
      from public.bookings where created_at between p_from and p_to
    ),
    'open_reports', (select count(*) from public.reports where status = 'open'),
    'open_disputes', (select count(*) from public.disputes where status = 'open'),
    'failed_payments', (select count(*) from public.transactions where status = 'failed' and created_at between p_from and p_to),
    -- Per currency. Platform earnings = 10% platform fee on completed sessions (card and cash).
    'revenue', coalesce((
      select jsonb_object_agg(currency, jsonb_build_object(
        'gross', card_volume + cash_volume, 'card', card_volume, 'cash', cash_volume,
        'platform', platform, 'refunds', refunds, 'fees_owed', fees_owed))
      from (
        select c.currency,
          coalesce((select sum((b.price ->> 'total')::int) from public.bookings b
                    where b.status = 'completed' and b.price ->> 'currency' = c.currency and b.ends_at between p_from and p_to
                      and b.payment_method is distinct from 'cash'), 0) as card_volume,
          coalesce((select sum((b.price ->> 'total')::int) from public.bookings b
                    where b.status = 'completed' and b.price ->> 'currency' = c.currency and b.ends_at between p_from and p_to
                      and b.payment_method = 'cash'), 0) as cash_volume,
          coalesce((select sum((b.price ->> 'studio_commission')::int + (b.price ->> 'service_fee')::int) from public.bookings b
                    where b.status = 'completed' and b.price ->> 'currency' = c.currency and b.ends_at between p_from and p_to), 0) as platform,
          coalesce((select sum(t.amount) from public.transactions t
                    where t.kind = 'refund' and t.status = 'succeeded' and t.currency = c.currency and t.created_at between p_from and p_to), 0) as refunds,
          coalesce((select sum(l.amount) from public.studio_fee_ledger l where l.currency = c.currency), 0) as fees_owed
        from (select distinct price ->> 'currency' as currency from public.bookings where status = 'completed') c
      ) x
    ), '{}'::jsonb),
    'top_studios', coalesce((
      select jsonb_agg(row_to_json(x)) from (
        select s.id, s.name, s.address ->> 'city' as city, count(b.id) as bookings, s.rating_average as rating
        from public.studios s join public.bookings b on b.studio_id = s.id
        where b.created_at between p_from and p_to and b.status in ('confirmed', 'completed')
        group by s.id order by count(b.id) desc limit 10
      ) x
    ), '[]'::jsonb),
    'top_areas', coalesce((
      select jsonb_agg(row_to_json(x)) from (
        select s.address ->> 'city' as city, nullif(s.address ->> 'area', '') as area, count(b.id) as bookings
        from public.studios s join public.bookings b on b.studio_id = s.id
        where b.created_at between p_from and p_to and b.status in ('confirmed', 'completed')
        group by 1, 2 order by count(b.id) desc limit 10
      ) x
    ), '[]'::jsonb),
    'bookings_per_day', coalesce((
      select jsonb_agg(row_to_json(x) order by x.day) from (
        select date_trunc('day', created_at)::date as day, count(*) as bookings
        from public.bookings where created_at between p_from and p_to and status <> 'awaiting_payment'
        group by 1
      ) x
    ), '[]'::jsonb)
  ) into result;
  return result;
end;
$$;

-- Admin-only view of users with their artist/studio info.
create or replace view public.admin_users with (security_invoker = true) as
select p.id, p.email, p.role, p.status, p.status_reason, p.is_verified, p.created_at,
  a.artist_name, a.city as artist_city,
  s.id as studio_id, s.name as studio_name,
  (select count(*) from public.bookings b where b.artist_id = p.id) as booking_count
from public.profiles p
left join public.artist_profiles a on a.id = p.id
left join public.studios s on s.owner_id = p.id;

-- ---------------------------------------------------------------------
-- 20260924000005_jobs.sql
-- ---------------------------------------------------------------------
-- EasySesh: scheduled jobs (pg_cron) and push delivery (pg_net → send-push edge function).
--
-- Setup (once per project), in the SQL editor:
--   select vault.create_secret('https://<project-ref>.supabase.co', 'project_url');
--   select vault.create_secret('<service-role-key>', 'service_role_key');

create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net with schema extensions;

create or replace function public.call_edge_function(p_name text, p_body jsonb default '{}'::jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  base_url text := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url');
  key text := (select decrypted_secret from vault.decrypted_secrets where name = 'service_role_key');
begin
  if base_url is null or key is null then
    return; -- not configured (e.g. local dev without secrets)
  end if;
  perform net.http_post(
    url := base_url || '/functions/v1/' || p_name,
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || key),
    body := p_body
  );
end;
$$;
revoke execute on function public.call_edge_function from public, anon, authenticated;

-- Every new notification is pushed to the user's devices (the function applies their settings).
create or replace function public.on_notification_insert()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  perform public.call_edge_function('send-push', jsonb_build_object('notification_id', new.id));
  return new;
end;
$$;
create trigger on_notification_insert after insert on public.notifications
  for each row execute function public.on_notification_insert();

-- Time-based booking transitions.
create or replace function public.run_booking_housekeeping()
returns void
language plpgsql security definer set search_path = public
as $$
begin
  -- Unpaid holds release the slot after 30 minutes.
  update public.bookings set status = 'expired'
  where status = 'awaiting_payment' and created_at < now() - interval '30 minutes';

  -- Requests the studio never answered expire at session start (authorisation is released by the edge function).
  update public.bookings set status = 'expired', payment_status = 'refunded'
  where status = 'pending_approval' and starts_at < now();

  -- Finished sessions complete (triggers review prompt; payouts/balance charges run in process-payouts).
  update public.bookings set status = 'completed'
  where status = 'confirmed' and ends_at < now();
end;
$$;

-- Session reminders 24h and 2h before start.
create or replace function public.queue_session_reminders()
returns void
language plpgsql security definer set search_path = public
as $$
declare
  b record;
begin
  for b in
    select * from public.bookings
    where status = 'confirmed' and reminder_24h_sent_at is null
      and starts_at between now() + interval '23 hours' and now() + interval '24 hours 15 minutes'
  loop
    perform public.notify(b.artist_id, 'session_reminder', 'Session tomorrow',
      b.session_type_name || ' at ' || b.studio_name || ', ' || public.format_local(b.starts_at, b.studio_id) || '.', b.id);
    update public.bookings set reminder_24h_sent_at = now() where id = b.id;
  end loop;

  for b in
    select * from public.bookings
    where status = 'confirmed' and reminder_2h_sent_at is null
      and starts_at between now() + interval '1 hour 45 minutes' and now() + interval '2 hours 15 minutes'
  loop
    perform public.notify(b.artist_id, 'session_reminder', 'Session in 2 hours',
      b.session_type_name || ' at ' || b.studio_name || '. See you there!', b.id);
    update public.bookings set reminder_2h_sent_at = now() where id = b.id;
  end loop;
end;
$$;

select cron.schedule('easysesh-booking-housekeeping', '*/10 * * * *', $$select public.run_booking_housekeeping()$$);
select cron.schedule('easysesh-session-reminders', '*/15 * * * *', $$select public.queue_session_reminders()$$);
select cron.schedule('easysesh-process-payouts', '7 * * * *', $$select public.call_edge_function('process-payouts')$$);

-- ---------------------------------------------------------------------
-- 20260925000001_cash_fees_compliance.sql
-- ---------------------------------------------------------------------
-- EasySesh: cash payments, platform-fee ledger for studios, terms acceptance (GDPR) and approval gating.
--
-- Money model: EasySesh takes 10% of every sale (price ->> 'studio_commission').
--  * Card:  the artist pays EasySesh, EasySesh pays the studio 90% (payouts).
--  * Cash:  the artist pays the studio at the session; the studio owes EasySesh 10%.
--           Owed fees are netted against the studio's next card payouts, invoiced, or paid manually.

-- ---------------------------------------------------------------------------
-- Fee ledger: positive = studio owes EasySesh, negative = settled.
-- ---------------------------------------------------------------------------
create table public.studio_fee_ledger (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid not null references public.studios (id) on delete cascade,
  booking_id uuid references public.bookings (id),
  payout_id uuid references public.payouts (id),
  invoice_id uuid,
  kind text not null check (kind in ('cash_commission', 'payout_offset', 'invoice_payment', 'manual_payment', 'waiver')),
  amount integer not null,
  currency text not null,
  note text,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);
create index studio_fee_ledger_studio_idx on public.studio_fee_ledger (studio_id, created_at desc);
create unique index studio_fee_ledger_commission_once on public.studio_fee_ledger (booking_id) where kind = 'cash_commission';
create unique index studio_fee_ledger_offset_once on public.studio_fee_ledger (payout_id) where kind = 'payout_offset';

create table public.studio_fee_invoices (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid not null references public.studios (id) on delete cascade,
  amount integer not null check (amount > 0),
  currency text not null,
  stripe_invoice_id text unique,
  hosted_invoice_url text,
  status text not null default 'open' check (status in ('open', 'paid', 'void')),
  created_at timestamptz not null default now(),
  paid_at timestamptz
);

create view public.studio_fee_balances with (security_invoker = true) as
select l.studio_id, s.name as studio_name, l.currency, sum(l.amount)::int as balance,
  max(l.created_at) filter (where l.kind = 'cash_commission') as last_commission_at
from public.studio_fee_ledger l join public.studios s on s.id = l.studio_id
group by l.studio_id, s.name, l.currency;

alter table public.studio_fee_ledger enable row level security;
alter table public.studio_fee_invoices enable row level security;
create policy "fee_ledger: owner or admin read" on public.studio_fee_ledger for select
  using (public.owns_studio(studio_id) or public.is_admin());
create policy "fee_invoices: owner or admin read" on public.studio_fee_invoices for select
  using (public.owns_studio(studio_id) or public.is_admin());

-- A completed cash session makes the platform fee payable.
create or replace function public.on_cash_booking_completed()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' and new.payment_method = 'cash' then
    insert into public.studio_fee_ledger (studio_id, booking_id, kind, amount, currency, note)
    values (new.studio_id, new.id, 'cash_commission', (new.price ->> 'studio_commission')::int, new.price ->> 'currency',
            'Platform fee for cash booking ' || new.reference)
    on conflict do nothing;
  end if;
  return new;
end;
$$;
create trigger on_cash_booking_completed after update of status on public.bookings
  for each row execute function public.on_cash_booking_completed();

-- Studio confirms it received the cash.
create or replace function public.mark_cash_received(p_booking_id uuid)
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  b public.bookings;
begin
  select * into b from public.bookings where id = p_booking_id for update;
  if b.id is null then raise exception 'not_found'; end if;
  if not public.owns_approved_studio(b.studio_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if b.payment_method is distinct from 'cash' then raise exception 'This booking was paid by card.'; end if;
  if b.status not in ('confirmed', 'completed') or b.starts_at > now() then
    raise exception 'You can confirm cash once the session has started.';
  end if;
  update public.bookings set payment_status = 'paid', cash_received_at = now(), changed_by = auth.uid()
  where id = b.id returning * into b;
  return b;
end;
$$;

-- Cash bookings not confirmed by the studio are treated as paid 3 days after the session
-- (the studio can open a dispute before that, e.g. for a no-show).
create or replace function public.run_cash_housekeeping()
returns void
language sql security definer set search_path = public
as $$
  update public.bookings set payment_status = 'paid', cash_received_at = coalesce(cash_received_at, now())
  where payment_method = 'cash' and payment_status = 'pay_at_studio'
    and status = 'completed' and ends_at < now() - interval '3 days';
$$;
select cron.schedule('easysesh-cash-housekeeping', '17 * * * *', $$select public.run_cash_housekeeping()$$);

-- ---------------------------------------------------------------------------
-- Terms acceptance (records version + time; required before using the app)
-- ---------------------------------------------------------------------------
create or replace function public.accept_terms(p_version text)
returns public.profiles
language plpgsql security definer set search_path = public
as $$
declare
  p public.profiles;
begin
  if coalesce(trim(p_version), '') = '' then raise exception 'Missing terms version.'; end if;
  update public.profiles set accepted_terms_version = p_version, accepted_terms_at = now()
  where id = auth.uid() returning * into p;
  if p.id is null then raise exception 'not_found'; end if;
  return p;
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin: settle or waive fees
-- ---------------------------------------------------------------------------
create or replace function public.admin_record_fee_settlement(p_studio_id uuid, p_amount integer, p_currency text, p_kind text, p_note text default null)
returns public.studio_fee_ledger
language plpgsql security definer set search_path = public
as $$
declare
  row public.studio_fee_ledger;
begin
  perform public.require_admin();
  if p_kind not in ('manual_payment', 'waiver') then raise exception 'Use manual_payment or waiver.'; end if;
  if p_amount <= 0 then raise exception 'Amount must be positive.'; end if;
  insert into public.studio_fee_ledger (studio_id, kind, amount, currency, note, created_by)
  values (p_studio_id, p_kind, -p_amount, upper(p_currency), p_note, auth.uid())
  returning * into row;
  return row;
end;
$$;

-- Keep the studio informed about what it owes.
create or replace function public.on_fee_ledger_insert()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  owner uuid;
begin
  select owner_id into owner from public.studios where id = new.studio_id;
  if new.kind = 'cash_commission' then
    perform public.notify(owner, 'system', 'Platform fee added',
      public.format_money(new.amount, new.currency) || ' for a cash booking. It will be deducted from your next payout.', new.booking_id, null, new.studio_id);
  elsif new.kind in ('invoice_payment', 'manual_payment') then
    perform public.notify(owner, 'system', 'Payment received', 'Thanks! We received ' || public.format_money(-new.amount, new.currency) || ' in platform fees.', null, null, new.studio_id);
  end if;
  return new;
end;
$$;
create trigger on_fee_ledger_insert after insert on public.studio_fee_ledger
  for each row execute function public.on_fee_ledger_insert();

-- ---------------------------------------------------------------------
-- 20260926000001_support.sql
-- ---------------------------------------------------------------------
-- EasySesh: in-app support. Users open tickets from the app, admins answer them in the admin dashboard.
-- Tables are read-only for clients; every write goes through the RPCs below.

create table public.support_tickets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  subject text not null check (char_length(subject) between 3 and 120),
  category text not null default 'other'
    check (category in ('account', 'booking', 'payment', 'studio', 'bug', 'other')),
  booking_id uuid references public.bookings (id) on delete set null,
  -- open: waiting for EasySesh · answered: waiting for the user · closed: done
  status text not null default 'open' check (status in ('open', 'answered', 'closed')),
  user_unread integer not null default 0,
  admin_unread integer not null default 0,
  last_message_preview text not null default '',
  last_message_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  closed_at timestamptz
);
create index support_tickets_user_idx on public.support_tickets (user_id, last_message_at desc);
create index support_tickets_status_idx on public.support_tickets (status, last_message_at desc);

create table public.support_messages (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.support_tickets (id) on delete cascade,
  sender_id uuid references public.profiles (id) on delete set null,
  from_admin boolean not null default false,
  body text not null check (char_length(body) between 1 and 4000),
  created_at timestamptz not null default now()
);
create index support_messages_ticket_idx on public.support_messages (ticket_id, created_at);

alter table public.support_tickets enable row level security;
alter table public.support_messages enable row level security;
create policy "support_tickets: own or admin read" on public.support_tickets for select
  using (user_id = auth.uid() or public.is_admin());
create policy "support_messages: own or admin read" on public.support_messages for select
  using (public.is_admin() or exists (select 1 from public.support_tickets t where t.id = ticket_id and t.user_id = auth.uid()));

-- Admin inbox rows with who wrote in.
create view public.admin_support_tickets with (security_invoker = true) as
select t.*, p.email as user_email, p.role as user_role,
  coalesce(nullif(a.artist_name, ''), nullif(s.name, ''), p.email) as user_name,
  b.reference as booking_reference
from public.support_tickets t
join public.profiles p on p.id = t.user_id
left join public.artist_profiles a on a.id = t.user_id
left join public.studios s on s.owner_id = t.user_id
left join public.bookings b on b.id = t.booking_id;

-- Adds a message to a ticket and updates its status, counters and preview.
create or replace function public.add_support_message(p_ticket_id uuid, p_body text, p_from_admin boolean)
returns public.support_messages
language plpgsql security definer set search_path = public
as $$
declare
  t public.support_tickets;
  m public.support_messages;
  new_id uuid := gen_random_uuid();
  body text := btrim(coalesce(p_body, ''));
begin
  -- Plain assignments on purpose: the Supabase SQL Editor treats "select ... in-to var"
  -- as a new table and breaks the function when this file is pasted.
  perform 1 from public.support_tickets where id = p_ticket_id for update;
  t := (select x from public.support_tickets x where x.id = p_ticket_id);
  if t.id is null then raise exception 'not_found'; end if;
  if body = '' then raise exception 'Write a message first.'; end if;
  if char_length(body) > 4000 then raise exception 'Message is too long (max 4000 characters).'; end if;

  insert into public.support_messages (id, ticket_id, sender_id, from_admin, body)
  values (new_id, t.id, auth.uid(), p_from_admin, body);
  m := (select x from public.support_messages x where x.id = new_id);

  update public.support_tickets set
    status = case when p_from_admin then 'answered' else 'open' end,
    user_unread = case when p_from_admin then user_unread + 1 else 0 end,
    admin_unread = case when p_from_admin then 0 else admin_unread + 1 end,
    last_message_preview = left(body, 140),
    last_message_at = m.created_at,
    closed_at = null
  where id = t.id;

  if p_from_admin then
    perform public.notify(t.user_id, 'system', 'EasySesh support replied', t.subject || ': ' || left(body, 120));
  end if;
  return m;
end;
$$;
revoke execute on function public.add_support_message from public, anon, authenticated;

-- App: open a new ticket with its first message.
create or replace function public.create_support_ticket(p_subject text, p_category text, p_body text, p_booking_id uuid default null)
returns public.support_tickets
language plpgsql security definer set search_path = public
as $$
declare
  new_id uuid := gen_random_uuid();
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_booking_id is not null and not exists (
    select 1 from public.bookings b
    where b.id = p_booking_id and (b.artist_id = auth.uid() or public.owns_studio(b.studio_id))
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  -- Light spam protection.
  if (select count(*) from public.support_tickets where user_id = auth.uid() and status <> 'closed') >= 5 then
    raise exception 'You already have 5 open requests. Please continue in one of them.';
  end if;
  if (select count(*) from public.support_tickets where user_id = auth.uid() and created_at > now() - interval '1 hour') >= 3 then
    raise exception 'Too many requests. Please try again later.';
  end if;

  insert into public.support_tickets (id, user_id, subject, category, booking_id)
  values (new_id, auth.uid(), btrim(coalesce(p_subject, '')), coalesce(nullif(p_category, ''), 'other'), p_booking_id);
  perform public.add_support_message(new_id, p_body, false);
  return (select x from public.support_tickets x where x.id = new_id);
end;
$$;

-- App (ticket owner) or admin dashboard: reply in a ticket.
create or replace function public.send_support_message(p_ticket_id uuid, p_body text)
returns public.support_messages
language plpgsql security definer set search_path = public
as $$
declare
  owner uuid;
begin
  owner := (select user_id from public.support_tickets where id = p_ticket_id);
  if owner is null then raise exception 'not_found'; end if;
  if public.is_admin() then
    return public.add_support_message(p_ticket_id, p_body, true);
  elsif owner = auth.uid() then
    return public.add_support_message(p_ticket_id, p_body, false);
  end if;
  raise exception 'forbidden' using errcode = '42501';
end;
$$;

-- Clears the unread counter for whoever is reading.
create or replace function public.mark_support_ticket_read(p_ticket_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if public.is_admin() then
    update public.support_tickets set admin_unread = 0 where id = p_ticket_id;
  else
    update public.support_tickets set user_unread = 0 where id = p_ticket_id and user_id = auth.uid();
  end if;
end;
$$;

-- The user can close their own ticket; admins can close or reopen any ticket.
create or replace function public.set_support_ticket_status(p_ticket_id uuid, p_status text)
returns public.support_tickets
language plpgsql security definer set search_path = public
as $$
declare
  t public.support_tickets;
begin
  if p_status not in ('open', 'answered', 'closed') then raise exception 'invalid status'; end if;
  perform 1 from public.support_tickets where id = p_ticket_id for update;
  t := (select x from public.support_tickets x where x.id = p_ticket_id);
  if t.id is null then raise exception 'not_found'; end if;
  if not public.is_admin() and not (t.user_id = auth.uid() and p_status = 'closed') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  update public.support_tickets
  set status = p_status, closed_at = case when p_status = 'closed' then now() end
  where id = t.id;
  return (select x from public.support_tickets x where x.id = t.id);
end;
$$;

-- Admins see new support messages live.
alter publication supabase_realtime add table public.support_messages;

-- ---------------------------------------------------------------------
-- 20260927000001_message_requests.sql
-- ---------------------------------------------------------------------
-- EasySesh: studios can start conversations with artists. A conversation a studio starts with an
-- artist it has no history with lands in the artist's "Requests" until the artist accepts it
-- (or replies). A declined request stays closed: the studio can't keep writing.

alter table public.conversations
  add column if not exists request_status text not null default 'accepted'
    check (request_status in ('accepted', 'pending', 'declined')),
  add column if not exists started_by_studio boolean not null default false,
  add column if not exists artist_avatar_url text;

-- Studios can't write in a conversation the artist declined.
drop policy if exists "messages: participants send" on public.messages;
create policy "messages: participants send" on public.messages for insert
  with check (
    sender_id = auth.uid() and kind = 'text' and public.is_active_user()
    and exists (
      select 1 from public.conversations c
      where c.id = conversation_id
        and (c.artist_id = auth.uid()
             or (public.owns_approved_studio(c.studio_id) and c.request_status <> 'declined'))
    )
  );

-- Artists a studio can message: search by name for studio owners with an approved studio.
create or replace function public.search_artists(p_query text)
returns table (id uuid, artist_name text, city text, genres text[], avatar_url text, is_verified boolean, has_booked boolean)
language plpgsql stable security definer set search_path = public
as $$
declare
  q text := btrim(coalesce(p_query, ''));
  my_studio uuid := (select s.id from public.studios s where s.owner_id = auth.uid() limit 1);
begin
  if my_studio is null or not public.owns_approved_studio(my_studio) then
    raise exception 'Only approved studios can message artists.' using errcode = '42501';
  end if;
  return query
    select a.id, a.artist_name, a.city, a.genres, a.avatar_url, a.is_verified,
      exists (select 1 from public.bookings b where b.artist_id = a.id and b.studio_id = my_studio) as has_booked
    from public.artist_profiles a
    join public.profiles p on p.id = a.id
    where p.status = 'active' and p.role = 'artist' and a.artist_name <> ''
      and (char_length(q) < 2 and exists (select 1 from public.bookings b where b.artist_id = a.id and b.studio_id = my_studio)
           or char_length(q) >= 2 and (a.artist_name ilike '%' || q || '%' or a.city ilike q || '%'))
    order by 7 desc, 6 desc, 2
    limit 30;
end;
$$;

-- Studio → artist: opens (or reuses) the general conversation and sends the first message.
create or replace function public.studio_start_conversation(p_artist_id uuid, p_body text)
returns public.conversations
language plpgsql security definer set search_path = public
as $$
declare
  v_body text := btrim(coalesce(p_body, ''));
  v_studio uuid := (select s.id from public.studios s where s.owner_id = auth.uid() limit 1);
  v_convo uuid;
  v_known boolean;
begin
  if v_studio is null or not public.owns_approved_studio(v_studio) or not public.is_active_user() then
    raise exception 'Only approved studios can message artists.' using errcode = '42501';
  end if;
  if v_body = '' then raise exception 'Write a message first.'; end if;
  if char_length(v_body) > 2000 then raise exception 'Messages can be at most 2000 characters.'; end if;
  if not exists (select 1 from public.profiles p where p.id = p_artist_id and p.role = 'artist' and p.status = 'active') then
    raise exception 'not_found';
  end if;

  v_convo := (select c.id from public.conversations c
              where c.artist_id = p_artist_id and c.studio_id = v_studio and c.booking_id is null);
  if v_convo is null then
    -- Spam protection for cold messages.
    if (select count(*) from public.conversations c
        where c.studio_id = v_studio and c.started_by_studio and c.created_at > now() - interval '1 day') >= 20 then
      raise exception 'You can start 20 new conversations per day. Try again tomorrow.';
    end if;
    -- Artists who already booked or wrote to the studio skip the request step.
    v_known := exists (select 1 from public.bookings b where b.artist_id = p_artist_id and b.studio_id = v_studio)
            or exists (select 1 from public.conversations c where c.artist_id = p_artist_id and c.studio_id = v_studio and not c.started_by_studio);
    v_convo := gen_random_uuid();
    insert into public.conversations (id, artist_id, studio_id, artist_name, studio_name, studio_photo_url, artist_avatar_url, request_status, started_by_studio)
    select v_convo, p_artist_id, s.id,
      coalesce(nullif(a.artist_name, ''), 'Artist'), s.name, s.photo_urls[1], a.avatar_url,
      case when v_known then 'accepted' else 'pending' end, true
    from public.studios s left join public.artist_profiles a on a.id = p_artist_id
    where s.id = v_studio;
  elsif (select c.request_status from public.conversations c where c.id = v_convo) = 'declined' then
    raise exception 'This artist isn''t accepting messages from your studio.';
  end if;

  insert into public.messages (conversation_id, sender_id, kind, body)
  values (v_convo, auth.uid(), 'text', v_body);
  return (select c from public.conversations c where c.id = v_convo);
end;
$$;

-- Artist accepts or declines a message request.
create or replace function public.respond_message_request(p_conversation_id uuid, p_accept boolean)
returns public.conversations
language plpgsql security definer set search_path = public
as $$
begin
  update public.conversations c
  set request_status = case when p_accept then 'accepted' else 'declined' end,
      artist_unread = case when p_accept then c.artist_unread else 0 end
  where c.id = p_conversation_id and c.artist_id = auth.uid();
  if not found then raise exception 'not_found'; end if;
  return (select c from public.conversations c where c.id = p_conversation_id);
end;
$$;

-- Messages: replying accepts a request; requests are announced as such.
create or replace function public.on_message_insert()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  c public.conversations;
  owner uuid;
  from_artist boolean;
begin
  c := (select x from public.conversations x where x.id = new.conversation_id);
  owner := (select s.owner_id from public.studios s where s.id = c.studio_id);
  from_artist := new.sender_id = c.artist_id;

  update public.conversations set
    last_message_preview = left(new.body, 140),
    last_message_at = new.created_at,
    artist_unread = artist_unread + case when new.sender_id is null or not from_artist then 1 else 0 end,
    studio_unread = studio_unread + case when new.sender_id is null or from_artist then 1 else 0 end,
    request_status = case when from_artist then 'accepted' else request_status end
  where id = c.id;

  if new.kind = 'text' and not (not from_artist and c.request_status = 'declined') then
    perform public.notify(
      case when from_artist then owner else c.artist_id end,
      'new_message',
      case
        when from_artist then c.artist_name
        when c.request_status = 'pending' then 'Message request · ' || c.studio_name
        else c.studio_name
      end,
      left(new.body, 140),
      c.booking_id, c.id
    );
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------
-- 20260928000001_support_ratings.sql
-- ---------------------------------------------------------------------
-- EasySesh: users rate how their support request was handled once it's closed.

alter table public.support_tickets
  add column if not exists rating smallint check (rating between 1 and 5),
  add column if not exists rating_comment text,
  add column if not exists rated_at timestamptz;

-- The ticket owner rates a closed ticket (can change it later).
create or replace function public.rate_support_ticket(p_ticket_id uuid, p_rating integer, p_comment text default null)
returns public.support_tickets
language plpgsql security definer set search_path = public
as $$
declare
  v_status text := (select t.status from public.support_tickets t where t.id = p_ticket_id and t.user_id = auth.uid());
begin
  if v_status is null then raise exception 'not_found'; end if;
  if v_status <> 'closed' then raise exception 'You can rate a request once it is closed.'; end if;
  if p_rating is null or p_rating not between 1 and 5 then raise exception 'Pick 1 to 5 stars.'; end if;
  update public.support_tickets
  set rating = p_rating,
      rating_comment = nullif(left(btrim(coalesce(p_comment, '')), 1000), ''),
      rated_at = now()
  where id = p_ticket_id;
  return (select t from public.support_tickets t where t.id = p_ticket_id);
end;
$$;

-- Admin view keeps its columns in sync with the table (t.* is expanded when the view is created).
drop view if exists public.admin_support_tickets;
create view public.admin_support_tickets with (security_invoker = true) as
select t.*, p.email as user_email, p.role as user_role,
  coalesce(nullif(a.artist_name, ''), nullif(s.name, ''), p.email) as user_name,
  b.reference as booking_reference
from public.support_tickets t
join public.profiles p on p.id = t.user_id
left join public.artist_profiles a on a.id = t.user_id
left join public.studios s on s.owner_id = t.user_id
left join public.bookings b on b.id = t.booking_id;

-- ---------------------------------------------------------------------
-- 20260929000001_badges_tags_promotions.sql
-- ---------------------------------------------------------------------
-- EasySesh: admin badge (cosmetic), admin-only studio tags and paid promotions.

-- ---------------------------------------------------------------------------
-- Columns. All three are set by admins/the server only (see the guards below).
-- ---------------------------------------------------------------------------
alter table public.artist_profiles
  add column if not exists has_admin_badge boolean not null default false;

alter table public.studios
  add column if not exists has_admin_badge boolean not null default false,
  add column if not exists admin_tags text[] not null default '{}',
  add column if not exists promoted_until timestamptz;

create index if not exists studios_promoted_idx on public.studios (promoted_until) where promoted_until is not null;

-- ---------------------------------------------------------------------------
-- Guards: owners/artists can't give themselves a badge, tags or a promotion.
-- ---------------------------------------------------------------------------
create or replace function public.guard_artist_profiles()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    if tg_op = 'INSERT' then
      new.is_verified := false;
      new.has_admin_badge := false;
    else
      new.is_verified := old.is_verified;
      new.has_admin_badge := old.has_admin_badge;
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create or replace function public.guard_studio_extras()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    if tg_op = 'INSERT' then
      new.has_admin_badge := false;
      new.admin_tags := '{}';
      new.promoted_until := null;
    else
      new.has_admin_badge := old.has_admin_badge;
      new.admin_tags := old.admin_tags;
      new.promoted_until := old.promoted_until;
    end if;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_studio_extras on public.studios;
create trigger guard_studio_extras before insert or update on public.studios
  for each row execute function public.guard_studio_extras();

-- ---------------------------------------------------------------------------
-- Promotions
-- ---------------------------------------------------------------------------
create table if not exists public.studio_promotions (
  id uuid primary key default gen_random_uuid(),
  studio_id uuid not null references public.studios (id) on delete cascade,
  package text not null check (package in ('week', 'two_weeks', 'month', 'custom')),
  days integer not null check (days between 1 and 365),
  amount integer not null default 0,
  currency text not null default 'EUR',
  status text not null default 'pending' check (status in ('pending', 'active', 'expired', 'cancelled')),
  source text not null default 'purchase' check (source in ('purchase', 'admin')),
  payment_intent_id text unique,
  starts_at timestamptz,
  ends_at timestamptz,
  note text,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);
create index if not exists studio_promotions_studio_idx on public.studio_promotions (studio_id, created_at desc);

alter table public.studio_promotions enable row level security;
drop policy if exists "studio_promotions: owner or admin read" on public.studio_promotions;
create policy "studio_promotions: owner or admin read" on public.studio_promotions for select
  using (public.owns_studio(studio_id) or public.is_admin());

-- Starts a paid or granted promotion: it runs after any promotion that is still active.
create or replace function public.activate_promotion(p_promotion_id uuid)
returns public.studio_promotions
language plpgsql security definer set search_path = public
as $$
declare
  v_studio uuid := (select p.studio_id from public.studio_promotions p where p.id = p_promotion_id);
  v_days integer := (select p.days from public.studio_promotions p where p.id = p_promotion_id);
  v_status text := (select p.status from public.studio_promotions p where p.id = p_promotion_id);
  v_start timestamptz;
begin
  if v_studio is null then raise exception 'not_found'; end if;
  if v_status = 'active' then
    return (select p from public.studio_promotions p where p.id = p_promotion_id);
  end if;
  v_start := greatest(now(), coalesce((select s.promoted_until from public.studios s where s.id = v_studio), now()));
  update public.studio_promotions
  set status = 'active', starts_at = v_start, ends_at = v_start + make_interval(days => v_days)
  where id = p_promotion_id;
  update public.studios
  set promoted_until = v_start + make_interval(days => v_days)
  where id = v_studio;
  perform public.notify((select s.owner_id from public.studios s where s.id = v_studio), 'system',
    'Your studio is promoted',
    'Your studio shows at the top of search with a Promoted tag until ' ||
      to_char(v_start + make_interval(days => v_days), 'DD Mon YYYY') || '.',
    null, null, v_studio);
  return (select p from public.studio_promotions p where p.id = p_promotion_id);
end;
$$;
revoke execute on function public.activate_promotion from public, anon, authenticated;

-- Marks finished promotions as expired (called by the housekeeping job).
create or replace function public.expire_promotions()
returns integer
language sql security definer set search_path = public
as $$
  with done as (
    update public.studio_promotions set status = 'expired'
    where status = 'active' and ends_at <= now()
    returning 1
  )
  select count(*)::int from done;
$$;
revoke execute on function public.expire_promotions from public, anon, authenticated;

-- Prices per package and currency (minor units). The app shows the same table (Promotions.swift).
create or replace function public.promotion_price(p_package text, p_currency text)
returns integer language sql immutable as $$
  select case upper(coalesce(p_currency, 'EUR'))
    when 'DKK' then case p_package when 'week' then 14900 when 'two_weeks' then 26900 when 'month' then 44900 end
    when 'SEK' then case p_package when 'week' then 21900 when 'two_weeks' then 39900 when 'month' then 65900 end
    when 'NOK' then case p_package when 'week' then 21900 when 'two_weeks' then 39900 when 'month' then 65900 end
    when 'GBP' then case p_package when 'week' then 1600 when 'two_weeks' then 2900 when 'month' then 4900 end
    when 'USD' then case p_package when 'week' then 2100 when 'two_weeks' then 3900 when 'month' then 6500 end
    when 'PLN' then case p_package when 'week' then 8900 when 'two_weeks' then 15900 when 'month' then 25900 end
    else case p_package when 'week' then 1900 when 'two_weeks' then 3500 when 'month' then 5900 end
  end;
$$;

create or replace function public.promotion_days(p_package text)
returns integer language sql immutable as $$
  select case p_package when 'week' then 7 when 'two_weeks' then 14 when 'month' then 30 end;
$$;

-- Studio orders a promotion. It starts when paid in the app (Stripe) or when an admin activates it
-- after payment by other means.
create or replace function public.request_promotion(p_package text)
returns public.studio_promotions
language plpgsql security definer set search_path = public
as $$
declare
  v_studio public.studios := (select s from public.studios s where s.owner_id = auth.uid() limit 1);
  v_id uuid := gen_random_uuid();
begin
  if v_studio.id is null or not public.owns_approved_studio(v_studio.id) then
    raise exception 'Only approved studios can be promoted.';
  end if;
  if public.promotion_days(p_package) is null then raise exception 'Unknown promotion package.'; end if;
  -- Only one open request at a time: replace an unpaid one.
  update public.studio_promotions set status = 'cancelled'
  where studio_id = v_studio.id and status = 'pending' and source = 'purchase';
  insert into public.studio_promotions (id, studio_id, package, days, amount, currency, source, created_by)
  values (v_id, v_studio.id, p_package, public.promotion_days(p_package),
          public.promotion_price(p_package, v_studio.currency), upper(v_studio.currency), 'purchase', auth.uid());
  return (select p from public.studio_promotions p where p.id = v_id);
end;
$$;

-- Studio withdraws an unpaid request.
create or replace function public.cancel_promotion_request(p_promotion_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  update public.studio_promotions p set status = 'cancelled'
  where p.id = p_promotion_id and p.status = 'pending' and (public.owns_studio(p.studio_id) or public.is_admin());
end;
$$;

-- Admin starts a requested promotion after the studio paid outside the app.
create or replace function public.admin_activate_promotion(p_promotion_id uuid)
returns public.studio_promotions
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  if not exists (select 1 from public.studio_promotions p where p.id = p_promotion_id and p.status = 'pending') then
    raise exception 'This request is not pending.';
  end if;
  return public.activate_promotion(p_promotion_id);
end;
$$;

-- Admin view of promotions with the studio name.
drop view if exists public.admin_promotions;
create view public.admin_promotions with (security_invoker = true) as
select p.*, s.name as studio_name, s.promoted_until
from public.studio_promotions p join public.studios s on s.id = p.studio_id;

-- ---------------------------------------------------------------------------
-- Admin tools
-- ---------------------------------------------------------------------------
-- Cosmetic "EasySesh team" badge on the artist profile and the user's studio. No extra rights.
create or replace function public.admin_set_admin_badge(p_user_id uuid, p_on boolean)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  update public.artist_profiles set has_admin_badge = p_on where id = p_user_id;
  update public.studios set has_admin_badge = p_on where owner_id = p_user_id;
end;
$$;

-- Special tags only admins can put on a studio (e.g. "Staff pick").
create or replace function public.admin_set_studio_tags(p_studio_id uuid, p_tags text[])
returns public.studios
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  update public.studios
  set admin_tags = coalesce((
    select array_agg(distinct left(btrim(t), 30)) from unnest(p_tags) as t where btrim(t) <> ''
  ), '{}')
  where id = p_studio_id;
  if not found then raise exception 'not_found'; end if;
  return (select s from public.studios s where s.id = p_studio_id);
end;
$$;

-- Free promotion granted by an admin (e.g. launch offer or compensation).
create or replace function public.admin_grant_promotion(p_studio_id uuid, p_days integer, p_note text default null)
returns public.studio_promotions
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  perform public.require_admin();
  if not exists (select 1 from public.studios s where s.id = p_studio_id and s.status = 'approved') then
    raise exception 'Only approved studios can be promoted.';
  end if;
  insert into public.studio_promotions (id, studio_id, package, days, source, note, created_by, currency)
  select v_id, p_studio_id, 'custom', p_days, 'admin', p_note, auth.uid(), s.currency
  from public.studios s where s.id = p_studio_id;
  return public.activate_promotion(v_id);
end;
$$;

-- Ends a studio's promotion now (admin).
create or replace function public.admin_end_promotion(p_studio_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  update public.studio_promotions set status = 'cancelled', ends_at = now()
  where studio_id = p_studio_id and status = 'active';
  update public.studios set promoted_until = null where id = p_studio_id;
end;
$$;

-- Admin user list shows the badge.
drop view if exists public.admin_users;
create view public.admin_users with (security_invoker = true) as
select p.id, p.email, p.role, p.status, p.status_reason, p.is_verified, p.created_at,
  a.artist_name, a.city as artist_city,
  s.id as studio_id, s.name as studio_name,
  coalesce(a.has_admin_badge, s.has_admin_badge, false) as has_admin_badge,
  (select count(*) from public.bookings b where b.artist_id = p.id) as booking_count
from public.profiles p
left join public.artist_profiles a on a.id = p.id
left join public.studios s on s.owner_id = p.id;

-- Artist search (studios starting a chat) shows the badge too. Return type changes, so drop first.
drop function if exists public.search_artists(text);
create or replace function public.search_artists(p_query text)
returns table (id uuid, artist_name text, city text, genres text[], avatar_url text, is_verified boolean, has_booked boolean, has_admin_badge boolean)
language plpgsql stable security definer set search_path = public
as $$
declare
  q text := btrim(coalesce(p_query, ''));
  my_studio uuid := (select s.id from public.studios s where s.owner_id = auth.uid() limit 1);
begin
  if my_studio is null or not public.owns_approved_studio(my_studio) then
    raise exception 'Only approved studios can message artists.' using errcode = '42501';
  end if;
  return query
    select a.id, a.artist_name, a.city, a.genres, a.avatar_url, a.is_verified,
      exists (select 1 from public.bookings b where b.artist_id = a.id and b.studio_id = my_studio) as has_booked,
      a.has_admin_badge
    from public.artist_profiles a
    join public.profiles p on p.id = a.id
    where p.status = 'active' and p.role = 'artist' and a.artist_name <> ''
      and (char_length(q) < 2 and exists (select 1 from public.bookings b where b.artist_id = a.id and b.studio_id = my_studio)
           or char_length(q) >= 2 and (a.artist_name ilike '%' || q || '%' or a.city ilike q || '%'))
    order by 7 desc, 6 desc, 2
    limit 30;
end;
$$;

-- Promotions end on their own (promoted_until); this keeps the history tidy.
select cron.schedule('easysesh-expire-promotions', '23 * * * *', $$select public.expire_promotions()$$);

-- ---------------------------------------------------------------------
-- 20260930000001_bookings_in_db.sql
-- ---------------------------------------------------------------------
-- EasySesh: booking actions that don't move card money run in the database, so booking works
-- before any edge function is deployed or Stripe is configured. Card flows (charging, capturing,
-- refunding) still use the edge functions; these RPCs raise 'needs_payment_service' for them.
-- Mirrors supabase/functions/_shared/pricing.ts and availability.ts.

-- Integer percentage with half-up rounding (same as pricing.ts `percent`).
create or replace function public.pct(p_amount integer, p_percent integer)
returns integer language sql immutable as $$
  select floor((p_amount::numeric * p_percent + 50) / 100)::int;
$$;

-- Whether [start, start + hours) fits the studio's opening hours (same day or an overnight window).
create or replace function public.fits_opening_hours(p_studio public.studios, p_start timestamptz, p_hours integer)
returns boolean
language plpgsql stable set search_path = public
as $$
declare
  v_local timestamp := p_start at time zone coalesce(nullif(p_studio.timezone, ''), 'UTC');
  v_weekday integer := extract(dow from v_local)::int + 1;  -- 1 = Sunday
  v_minute integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_duration integer := p_hours * 60;
  v_day integer;
  v_offset integer;
  v_hours jsonb;
  v_opens integer;
  v_closes integer;
begin
  for i in 0..1 loop
    v_day := case when i = 0 then v_weekday when v_weekday = 1 then 7 else v_weekday - 1 end;
    v_offset := i * 24 * 60;
    v_hours := (select h from jsonb_array_elements(p_studio.opening_hours) as h where (h ->> 'weekday')::int = v_day limit 1);
    continue when v_hours is null or coalesce((v_hours ->> 'is_closed')::boolean, false);
    v_opens := (v_hours ->> 'opens_at')::int;
    v_closes := (v_hours ->> 'closes_at')::int;
    if v_closes <= v_opens then v_closes := v_closes + 24 * 60; end if;
    if v_minute + v_offset >= v_opens and v_minute + v_offset + v_duration <= v_closes then
      return true;
    end if;
  end loop;
  return false;
end;
$$;

-- Timing rules: notice, how far ahead, opening hours and conflicts (with buffer).
create or replace function public.check_booking_slot(p_studio public.studios, p_start timestamptz, p_hours integer, p_ignore_booking uuid default null)
returns void
language plpgsql stable security definer set search_path = public
as $$
declare
  v_policy jsonb := coalesce(p_studio.booking_policy, '{}'::jsonb);
  v_notice integer := coalesce((v_policy ->> 'minimum_notice_hours')::int, 0);
  v_ahead integer := coalesce((v_policy ->> 'max_advance_days')::int, 90);
  v_buffer interval := make_interval(mins => coalesce((v_policy ->> 'buffer_minutes')::int, 0));
  v_end timestamptz := p_start + make_interval(hours => p_hours);
begin
  if p_start < now() + make_interval(hours => v_notice) then
    raise exception 'This studio needs at least % hours'' notice.', v_notice;
  end if;
  if p_start > now() + make_interval(days => v_ahead + 1) then
    raise exception 'You can book at most % days ahead.', v_ahead;
  end if;
  if not public.fits_opening_hours(p_studio, p_start, p_hours) then
    raise exception 'slot_unavailable';
  end if;
  if exists (
    select 1 from public.bookings b
    where b.studio_id = p_studio.id and b.id is distinct from p_ignore_booking
      and b.status in ('awaiting_payment', 'pending_approval', 'confirmed')
      and b.starts_at < v_end + v_buffer and b.ends_at > p_start - v_buffer
  ) or exists (
    select 1 from public.blocked_slots s
    where s.studio_id = p_studio.id and s.starts_at < v_end + v_buffer and s.ends_at > p_start - v_buffer
  ) then
    raise exception 'slot_unavailable';
  end if;
end;
$$;

-- Artist creates a booking (held for 30 minutes in awaiting_payment). Price is computed here.
create or replace function public.create_booking(
  p_studio_id uuid,
  p_session_type_id text,
  p_starts_at timestamptz,
  p_hours integer,
  p_add_ons jsonb default '[]'::jsonb,
  p_notes text default ''
) returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_studio public.studios;
  v_type jsonb;
  v_rate integer;
  v_min integer;
  v_session integer;
  v_addons_amount integer := 0;
  v_booked jsonb := '[]'::jsonb;
  v_addon jsonb;
  v_qty integer;
  v_amount integer;
  v_subtotal integer;
  v_fee integer;
  v_total integer;
  v_deposit_pct integer;
  v_deposit integer;
  v_due_now integer;
  v_commission integer;
  v_id uuid := gen_random_uuid();
  v_reference text;
  v_artist_name text;
begin
  if not exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'artist' and p.status = 'active') then
    raise exception 'Only artist accounts can book sessions.';
  end if;
  v_studio := (select s from public.studios s where s.id = p_studio_id);
  if v_studio.id is null or v_studio.status <> 'approved' or not v_studio.is_active then
    raise exception 'not_found';
  end if;

  v_type := (select t from jsonb_array_elements(v_studio.session_types) as t where t ->> 'id' = p_session_type_id limit 1);
  if v_type is null then raise exception 'Unknown session type.'; end if;
  v_rate := (v_type ->> 'hourly_rate')::int;
  v_min := coalesce((v_type ->> 'minimum_hours')::int, 1);
  if p_hours is null or p_hours < v_min then
    raise exception 'Minimum % hours for %.', v_min, v_type ->> 'name';
  end if;
  if p_hours > 12 then raise exception 'Sessions can be at most 12 hours.'; end if;

  perform public.check_booking_slot(v_studio, p_starts_at, p_hours);

  -- Add-ons: [{ "id": "...", "quantity": n }]
  for v_addon in select a from jsonb_array_elements(coalesce(v_studio.add_ons, '[]'::jsonb)) as a loop
    v_qty := least(greatest(coalesce((
      select floor((x ->> 'quantity')::numeric)::int from jsonb_array_elements(coalesce(p_add_ons, '[]'::jsonb)) as x
      where x ->> 'id' = v_addon ->> 'id' limit 1), 0), 0), 50);
    continue when v_qty = 0;
    v_amount := case v_addon ->> 'unit'
      when 'per_hour' then (v_addon ->> 'price')::int * p_hours
      when 'per_session' then (v_addon ->> 'price')::int
      else (v_addon ->> 'price')::int * v_qty
    end;
    v_addons_amount := v_addons_amount + v_amount;
    v_booked := v_booked || jsonb_build_object('id', v_addon ->> 'id', 'name', v_addon ->> 'name', 'quantity', v_qty, 'amount', v_amount);
  end loop;

  v_session := v_rate * p_hours;
  v_subtotal := v_session + v_addons_amount;
  v_fee := 0;  -- artists pay the studio's price; EasySesh takes 10% from the studio
  v_total := v_subtotal + v_fee;
  v_deposit_pct := least(greatest(coalesce((v_studio.booking_policy ->> 'deposit_percent')::int, 0), 0), 100);
  v_deposit := case when v_deposit_pct > 0 and v_deposit_pct < 100 then public.pct(v_subtotal, v_deposit_pct) else 0 end;
  v_due_now := case when v_deposit > 0 then v_deposit + v_fee else v_total end;
  v_commission := public.pct(v_subtotal, coalesce(v_studio.platform_fee_percent, 10));

  v_reference := 'ES-' || upper(substr(md5(gen_random_uuid()::text || clock_timestamp()::text), 1, 6));
  v_artist_name := coalesce(nullif((select a.artist_name from public.artist_profiles a where a.id = auth.uid()), ''),
                            (select p.email from public.profiles p where p.id = auth.uid()));

  begin
    insert into public.bookings (id, reference, artist_id, studio_id, artist_name, studio_name, session_type_id, session_type_name,
      starts_at, ends_at, hours, add_ons, price, notes, changed_by)
    values (v_id, v_reference, auth.uid(), v_studio.id, v_artist_name, v_studio.name, p_session_type_id, v_type ->> 'name',
      p_starts_at, p_starts_at + make_interval(hours => p_hours), p_hours, v_booked,
      jsonb_build_object(
        'currency', v_studio.currency, 'hourly_rate', v_rate, 'hours', p_hours,
        'session_amount', v_session, 'add_ons_amount', v_addons_amount, 'subtotal', v_subtotal,
        'service_fee', v_fee, 'total', v_total, 'deposit_amount', v_deposit,
        'due_now', v_due_now, 'due_later', v_total - v_due_now,
        'studio_commission', v_commission, 'studio_payout', v_subtotal - v_commission),
      left(coalesce(p_notes, ''), 1000), auth.uid());
  exception when exclusion_violation then
    raise exception 'slot_unavailable' using errcode = '23P01';
  end;
  return (select b from public.bookings b where b.id = v_id);
end;
$$;

-- Artist chooses to pay cash at the studio.
create or replace function public.confirm_cash_booking(p_booking_id uuid)
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
  v_studio public.studios;
  v_policy jsonb;
begin
  if v_booking.id is null or v_booking.artist_id <> auth.uid() then raise exception 'not_found'; end if;
  if v_booking.status <> 'awaiting_payment' then raise exception 'This booking is no longer awaiting payment.'; end if;
  v_studio := (select s from public.studios s where s.id = v_booking.studio_id);
  v_policy := coalesce(v_studio.booking_policy, '{}'::jsonb);
  if not coalesce((v_policy ->> 'accepts_cash')::boolean, true) or coalesce((v_policy ->> 'deposit_percent')::int, 0) > 0 then
    raise exception 'This studio only accepts payment in the app.';
  end if;
  update public.bookings set
    status = case when coalesce((v_policy ->> 'instant_book')::boolean, true) then 'confirmed'::public.booking_status else 'pending_approval'::public.booking_status end,
    payment_method = 'cash', payment_status = 'pay_at_studio', changed_by = auth.uid()
  where id = p_booking_id;
  return (select b from public.bookings b where b.id = p_booking_id);
end;
$$;

-- Who is acting on a booking: 'artist' or 'studio_owner' (approved studio only).
create or replace function public.booking_actor(p_booking public.bookings)
returns text
language plpgsql stable security definer set search_path = public
as $$
begin
  if p_booking.artist_id = auth.uid() then return 'artist'; end if;
  if public.owns_approved_studio(p_booking.studio_id) then return 'studio_owner'; end if;
  raise exception 'forbidden' using errcode = '42501';
end;
$$;

-- Card money involved → the payment service (edge function) has to handle refunds/captures.
create or replace function public.booking_has_card_money(p_booking public.bookings)
returns boolean language sql immutable as $$
  select coalesce(p_booking.payment_method::text, '') <> 'cash'
     and p_booking.payment_status not in ('unpaid', 'pay_at_studio', 'failed');
$$;

create or replace function public.cancel_booking(p_booking_id uuid, p_reason text default '')
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
  v_actor text;
  v_reason text := left(btrim(coalesce(p_reason, '')), 500);
begin
  if v_booking.id is null then raise exception 'not_found'; end if;
  v_actor := public.booking_actor(v_booking);
  if v_booking.status not in ('pending_approval', 'confirmed') or v_booking.starts_at <= now() then
    raise exception 'This booking can no longer be cancelled.';
  end if;
  if v_actor = 'studio_owner' and v_reason = '' then
    raise exception 'Please tell the artist why you''re cancelling.';
  end if;
  if public.booking_has_card_money(v_booking) then raise exception 'needs_payment_service'; end if;
  update public.bookings set
    status = 'cancelled', cancelled_by = v_actor::public.user_role, cancellation_reason = nullif(v_reason, ''),
    payment_status = 'unpaid', changed_by = auth.uid()
  where id = p_booking_id;
  return (select b from public.bookings b where b.id = p_booking_id);
end;
$$;

create or replace function public.respond_booking(p_booking_id uuid, p_accept boolean, p_message text default null)
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
begin
  if v_booking.id is null then raise exception 'not_found'; end if;
  if not public.owns_approved_studio(v_booking.studio_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_booking.status <> 'pending_approval' then raise exception 'This request has already been handled.'; end if;
  if public.booking_has_card_money(v_booking) then raise exception 'needs_payment_service'; end if;
  if p_accept then
    update public.bookings set status = 'confirmed', changed_by = auth.uid() where id = p_booking_id;
  else
    update public.bookings set status = 'declined', payment_status = 'unpaid',
      cancellation_reason = nullif(left(btrim(coalesce(p_message, '')), 500), ''), changed_by = auth.uid()
    where id = p_booking_id;
  end if;
  return (select b from public.bookings b where b.id = p_booking_id);
end;
$$;

-- Same duration and price, new start time. No money moves, so this never needs the payment service.
create or replace function public.reschedule_booking(p_booking_id uuid, p_starts_at timestamptz)
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
  v_studio public.studios;
begin
  if v_booking.id is null then raise exception 'not_found'; end if;
  perform public.booking_actor(v_booking);
  if v_booking.status <> 'confirmed' or v_booking.starts_at <= now() then
    raise exception 'This booking can''t be changed.';
  end if;
  v_studio := (select s from public.studios s where s.id = v_booking.studio_id);
  perform public.check_booking_slot(v_studio, p_starts_at, v_booking.hours, v_booking.id);
  begin
    update public.bookings set starts_at = p_starts_at, ends_at = p_starts_at + make_interval(hours => v_booking.hours),
      changed_by = auth.uid()
    where id = p_booking_id;
  exception when exclusion_violation then
    raise exception 'slot_unavailable' using errcode = '23P01';
  end;
  return (select b from public.bookings b where b.id = p_booking_id);
end;
$$;

-- ---------------------------------------------------------------------
-- 20261001000001_artist_ratings_notifications.sql
-- ---------------------------------------------------------------------
-- EasySesh: studios rate artists after a completed session; users can delete their notifications.

-- Notifications: swipe to delete.
drop policy if exists "notifications: own delete" on public.notifications;
create policy "notifications: own delete" on public.notifications for delete using (user_id = auth.uid());

-- Artist ratings (given by studios).
alter table public.artist_profiles
  add column if not exists rating_average numeric(3, 2) not null default 0,
  add column if not exists review_count integer not null default 0;

create table if not exists public.artist_reviews (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.bookings (id) on delete cascade,
  studio_id uuid not null references public.studios (id) on delete cascade,
  artist_id uuid not null references public.profiles (id) on delete cascade,
  studio_name text not null,
  rating smallint not null check (rating between 1 and 5),
  text text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists artist_reviews_artist_idx on public.artist_reviews (artist_id, created_at desc);

alter table public.artist_reviews enable row level security;
drop policy if exists "artist_reviews: read" on public.artist_reviews;
create policy "artist_reviews: read" on public.artist_reviews for select to authenticated using (true);

-- Artists can't edit their own rating numbers.
create or replace function public.guard_artist_profiles()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    if tg_op = 'INSERT' then
      new.is_verified := false;
      new.has_admin_badge := false;
      new.rating_average := 0;
      new.review_count := 0;
    else
      new.is_verified := old.is_verified;
      new.has_admin_badge := old.has_admin_badge;
      new.rating_average := old.rating_average;
      new.review_count := old.review_count;
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

-- Studio rates the artist of one of its completed bookings (can update it later).
create or replace function public.review_artist(p_booking_id uuid, p_rating integer, p_text text default '')
returns public.artist_reviews
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
  v_is_new boolean;
begin
  if v_booking.id is null then raise exception 'not_found'; end if;
  if not public.owns_approved_studio(v_booking.studio_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_booking.status <> 'completed' then raise exception 'You can rate the artist after the session is completed.'; end if;
  if p_rating is null or p_rating not between 1 and 5 then raise exception 'Pick 1 to 5 stars.'; end if;
  v_is_new := not exists (select 1 from public.artist_reviews r where r.booking_id = p_booking_id);

  insert into public.artist_reviews (booking_id, studio_id, artist_id, studio_name, rating, text)
  values (v_booking.id, v_booking.studio_id, v_booking.artist_id, v_booking.studio_name, p_rating, left(btrim(coalesce(p_text, '')), 1000))
  on conflict (booking_id) do update set rating = excluded.rating, text = excluded.text, updated_at = now();

  -- Ratings removed after a dispute (is_hidden, added later) don't count.
  update public.artist_profiles a set
    rating_average = coalesce((select round(avg(r.rating)::numeric, 2) from public.artist_reviews r where r.artist_id = a.id and not r.is_hidden), 0),
    review_count = (select count(*) from public.artist_reviews r where r.artist_id = a.id and not r.is_hidden)
  where a.id = v_booking.artist_id;

  if v_is_new then
    perform public.notify(v_booking.artist_id, 'new_review', v_booking.studio_name || ' rated you',
      repeat('★', p_rating) || repeat('☆', 5 - p_rating), v_booking.id, null, v_booking.studio_id);
  end if;
  return (select r from public.artist_reviews r where r.booking_id = p_booking_id);
end;
$$;

-- ---------------------------------------------------------------------
-- 20261002000001_fee_enforcement.sql
-- ---------------------------------------------------------------------
-- EasySesh: collecting platform fees studios owe for cash bookings.
--  1. Fees are deducted from the studio's next card payout (process-payouts, unchanged).
--  2. Whatever is still owed on the 1st of the month is invoiced, due in 14 days.
--  3. Overdue: reminder at the due date, final notice after 7 days.
--  4. 14 days after the due date the studio is suspended (removed from EasySesh) and the invoice
--     goes to debt collection / legal action. Admins can record payment and reinstate the studio.

alter table public.studio_fee_invoices
  add column if not exists due_at timestamptz,
  add column if not exists reminder_sent_at timestamptz,
  add column if not exists final_notice_at timestamptz,
  add column if not exists collections_at timestamptz;
update public.studio_fee_invoices set due_at = created_at + interval '14 days' where due_at is null;
alter table public.studio_fee_invoices alter column due_at set default now() + interval '14 days';

alter table public.studio_fee_invoices drop constraint if exists studio_fee_invoices_status_check;
alter table public.studio_fee_invoices add constraint studio_fee_invoices_status_check
  check (status in ('open', 'paid', 'void', 'collections'));

-- Invoices whatever is still owed after payouts. Runs monthly; safe to run again.
create or replace function public.create_fee_invoices()
returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select l.studio_id, l.currency, sum(l.amount)::int as balance,
      coalesce((select sum(i.amount) from public.studio_fee_invoices i
                where i.studio_id = l.studio_id and i.currency = l.currency and i.status in ('open', 'collections')), 0)::int as invoiced
    from public.studio_fee_ledger l
    group by l.studio_id, l.currency
  loop
    continue when v_row.balance - v_row.invoiced <= 0;
    insert into public.studio_fee_invoices (studio_id, amount, currency, due_at)
    values (v_row.studio_id, v_row.balance - v_row.invoiced, v_row.currency, now() + interval '14 days');
    perform public.notify((select s.owner_id from public.studios s where s.id = v_row.studio_id), 'system',
      'Invoice for platform fees',
      'You owe ' || public.format_money(v_row.balance - v_row.invoiced, v_row.currency) ||
      ' in platform fees for cash bookings that could not be deducted from payouts. Please pay within 14 days (' ||
      to_char(now() + interval '14 days', 'DD Mon YYYY') || ').', null, null, v_row.studio_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
revoke execute on function public.create_fee_invoices from public, anon, authenticated;

-- Reminders, final notice, suspension and debt collection. Runs daily.
create or replace function public.run_fee_enforcement()
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_invoice record;
  v_owner uuid;
begin
  for v_invoice in select i.* from public.studio_fee_invoices i where i.status = 'open' and i.due_at < now() loop
    v_owner := (select s.owner_id from public.studios s where s.id = v_invoice.studio_id);

    if v_invoice.due_at < now() - interval '14 days' then
      update public.studio_fee_invoices set status = 'collections', collections_at = now() where id = v_invoice.id;
      update public.studios set status = 'suspended', is_active = false,
        admin_note = 'Suspended for unpaid platform fees (' || public.format_money(v_invoice.amount, v_invoice.currency) ||
                     '). The debt has been handed over for collection.'
      where id = v_invoice.studio_id and status <> 'suspended';
      perform public.notify(v_owner, 'system', 'Studio suspended – unpaid platform fees',
        'Your invoice of ' || public.format_money(v_invoice.amount, v_invoice.currency) ||
        ' is more than 14 days overdue. Your studio has been removed from EasySesh and the debt has been handed over for collection and legal action. Contact support to settle it.',
        null, null, v_invoice.studio_id);
    elsif v_invoice.due_at < now() - interval '7 days' and v_invoice.final_notice_at is null then
      update public.studio_fee_invoices set final_notice_at = now() where id = v_invoice.id;
      perform public.notify(v_owner, 'system', 'Final notice: unpaid platform fees',
        'Your invoice of ' || public.format_money(v_invoice.amount, v_invoice.currency) ||
        ' is overdue. Pay within 7 days, otherwise your studio will be removed from EasySesh and the debt handed over for collection and legal action.',
        null, null, v_invoice.studio_id);
    elsif v_invoice.reminder_sent_at is null then
      update public.studio_fee_invoices set reminder_sent_at = now() where id = v_invoice.id;
      perform public.notify(v_owner, 'system', 'Reminder: platform fee invoice due',
        'Your invoice of ' || public.format_money(v_invoice.amount, v_invoice.currency) || ' was due on ' ||
        to_char(v_invoice.due_at, 'DD Mon YYYY') || '. Please pay it as soon as possible.', null, null, v_invoice.studio_id);
    end if;
  end loop;
end;
$$;
revoke execute on function public.run_fee_enforcement from public, anon, authenticated;

-- When payments bring the balance to zero, open invoices are marked paid.
create or replace function public.settle_fee_invoices()
returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if new.amount < 0 and (select coalesce(sum(l.amount), 0) from public.studio_fee_ledger l
                          where l.studio_id = new.studio_id and l.currency = new.currency) <= 0 then
    update public.studio_fee_invoices set status = 'paid', paid_at = now()
    where studio_id = new.studio_id and currency = new.currency and status in ('open', 'collections');
  end if;
  return new;
end;
$$;
drop trigger if exists settle_fee_invoices on public.studio_fee_ledger;
create trigger settle_fee_invoices after insert on public.studio_fee_ledger
  for each row execute function public.settle_fee_invoices();

-- Admin: reinstate a studio that was suspended for unpaid fees once the debt is settled.
create or replace function public.admin_reinstate_studio(p_studio_id uuid)
returns public.studios
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  if (select coalesce(sum(l.amount), 0) from public.studio_fee_ledger l where l.studio_id = p_studio_id) > 0 then
    raise exception 'This studio still owes platform fees. Record the payment first.';
  end if;
  update public.studios set status = 'approved', is_active = true, admin_note = null where id = p_studio_id;
  return (select s from public.studios s where s.id = p_studio_id);
end;
$$;

select cron.schedule('easysesh-fee-invoices', '10 6 1 * *', $$select public.create_fee_invoices()$$);
select cron.schedule('easysesh-fee-enforcement', '20 6 * * *', $$select public.run_fee_enforcement()$$);

-- ---------------------------------------------------------------------
-- 20261003000001_deals_contact_rating_disputes.sql
-- ---------------------------------------------------------------------
-- EasySesh: per-studio platform fee (special deals), email + phone required in applications,
-- and disputes of ratings (studios dispute artists' reviews, artists dispute studios' ratings).

-- ---------------------------------------------------------------------------
-- Special deals: each studio can have its own platform fee (default 10%), set by an admin.
-- ---------------------------------------------------------------------------
alter table public.studios
  add column if not exists platform_fee_percent smallint not null default 10 check (platform_fee_percent between 0 and 30);

create or replace function public.guard_studio_extras()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    if tg_op = 'INSERT' then
      new.has_admin_badge := false;
      new.admin_tags := '{}';
      new.promoted_until := null;
      new.platform_fee_percent := 10;
    else
      new.has_admin_badge := old.has_admin_badge;
      new.admin_tags := old.admin_tags;
      new.promoted_until := old.promoted_until;
      new.platform_fee_percent := old.platform_fee_percent;
    end if;
  end if;
  return new;
end;
$$;

create or replace function public.admin_set_platform_fee(p_studio_id uuid, p_percent integer)
returns public.studios
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  if p_percent is null or p_percent not between 0 and 30 then raise exception 'The platform fee must be between 0 and 30%%.'; end if;
  update public.studios set platform_fee_percent = p_percent where id = p_studio_id;
  if not found then raise exception 'not_found'; end if;
  return (select s from public.studios s where s.id = p_studio_id);
end;
$$;

-- ---------------------------------------------------------------------------
-- Applications need both an email address and a phone number.
-- ---------------------------------------------------------------------------
create or replace function public.studio_validation_problems(s public.studios)
returns text[]
language plpgsql stable
as $$
declare
  problems text[] := '{}';
begin
  if char_length(trim(s.name)) < 3 then problems := array_append(problems, 'Add your studio''s name.'::text); end if;
  if char_length(s.description) < 40 then problems := array_append(problems, 'Write a description of at least 40 characters.'::text); end if;
  if cardinality(s.photo_urls) = 0 then problems := array_append(problems, 'Add at least one photo.'::text); end if;
  if coalesce(s.address ->> 'street', '') = '' or coalesce(s.address ->> 'city', '') = '' then problems := array_append(problems, 'Add the studio''s address.'::text); end if;
  if s.latitude = 0 and s.longitude = 0 then problems := array_append(problems, 'Place your studio on the map.'::text); end if;
  if coalesce(s.contact ->> 'email', '') !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then problems := array_append(problems, 'Add a valid email address.'::text); end if;
  if length(regexp_replace(coalesce(s.contact ->> 'phone', ''), '[^0-9]', '', 'g')) < 6 then problems := array_append(problems, 'Add a phone number.'::text); end if;
  if jsonb_array_length(s.session_types) = 0 or exists (
       select 1 from jsonb_array_elements(s.session_types) as t where coalesce((t.value ->> 'hourly_rate')::int, 0) <= 0) then
    problems := array_append(problems, 'Set a price for each session type.'::text);
  end if;
  if not exists (select 1 from jsonb_array_elements(s.opening_hours) as h where not coalesce((h.value ->> 'is_closed')::boolean, false)) then
    problems := array_append(problems, 'Set your opening hours.'::text);
  end if;
  if cardinality(s.genres) = 0 then problems := array_append(problems, 'Pick at least one genre.'::text); end if;
  return problems;
end;
$$;

-- ---------------------------------------------------------------------------
-- Rating disputes
-- ---------------------------------------------------------------------------
alter table public.artist_reviews add column if not exists is_hidden boolean not null default false;

create table if not exists public.rating_disputes (
  id uuid primary key default gen_random_uuid(),
  review_type text not null check (review_type in ('studio_review', 'artist_review')),
  review_id uuid not null,
  opened_by uuid not null references public.profiles (id) on delete cascade,
  reason text not null check (char_length(reason) between 10 and 1000),
  status text not null default 'open' check (status in ('open', 'removed', 'kept')),
  admin_note text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  unique (review_type, review_id)
);
alter table public.rating_disputes enable row level security;
drop policy if exists "rating_disputes: own or admin read" on public.rating_disputes;
create policy "rating_disputes: own or admin read" on public.rating_disputes for select
  using (opened_by = auth.uid() or public.is_admin());

create or replace function public.refresh_artist_rating(p_artist_id uuid)
returns void language sql security definer set search_path = public as $$
  update public.artist_profiles a set
    rating_average = coalesce((select round(avg(r.rating)::numeric, 2) from public.artist_reviews r where r.artist_id = a.id and not r.is_hidden), 0),
    review_count = (select count(*) from public.artist_reviews r where r.artist_id = a.id and not r.is_hidden)
  where a.id = p_artist_id;
$$;
revoke execute on function public.refresh_artist_rating from public, anon, authenticated;

-- The rated party disputes a rating: the studio (review of its studio) or the artist (rating by a studio).
create or replace function public.dispute_rating(p_review_type text, p_review_id uuid, p_reason text)
returns public.rating_disputes
language plpgsql security definer set search_path = public
as $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_allowed boolean;
  v_id uuid := gen_random_uuid();
begin
  if char_length(v_reason) < 10 then raise exception 'Tell us why the rating is unfair (at least 10 characters).'; end if;
  v_allowed := case p_review_type
    when 'studio_review' then exists (select 1 from public.reviews r where r.id = p_review_id and public.owns_studio(r.studio_id))
    when 'artist_review' then exists (select 1 from public.artist_reviews r where r.id = p_review_id and r.artist_id = auth.uid())
    else false end;
  if not v_allowed then raise exception 'forbidden' using errcode = '42501'; end if;
  if exists (select 1 from public.rating_disputes d where d.review_type = p_review_type and d.review_id = p_review_id) then
    raise exception 'This rating has already been disputed.';
  end if;
  insert into public.rating_disputes (id, review_type, review_id, opened_by, reason)
  values (v_id, p_review_type, p_review_id, auth.uid(), left(v_reason, 1000));
  return (select d from public.rating_disputes d where d.id = v_id);
end;
$$;

-- Admin decides: remove the rating (hidden and no longer counted) or keep it.
create or replace function public.admin_resolve_rating_dispute(p_dispute_id uuid, p_remove boolean, p_note text default null)
returns public.rating_disputes
language plpgsql security definer set search_path = public
as $$
declare
  v_dispute public.rating_disputes := (select d from public.rating_disputes d where d.id = p_dispute_id);
  v_artist uuid;
begin
  perform public.require_admin();
  if v_dispute.id is null then raise exception 'not_found'; end if;
  if v_dispute.status <> 'open' then raise exception 'This dispute is already resolved.'; end if;
  if p_remove then
    if v_dispute.review_type = 'studio_review' then
      update public.reviews set is_hidden = true where id = v_dispute.review_id;
    else
      update public.artist_reviews set is_hidden = true where id = v_dispute.review_id;
      v_artist := (select r.artist_id from public.artist_reviews r where r.id = v_dispute.review_id);
      perform public.refresh_artist_rating(v_artist);
    end if;
  end if;
  update public.rating_disputes set status = case when p_remove then 'removed' else 'kept' end,
    admin_note = nullif(btrim(coalesce(p_note, '')), ''), resolved_at = now()
  where id = p_dispute_id;
  perform public.notify(v_dispute.opened_by, 'system',
    case when p_remove then 'Rating removed' else 'Rating dispute reviewed' end,
    case when p_remove then 'We reviewed your dispute and removed the rating.'
         else 'We reviewed your dispute and the rating stays.' end || coalesce(' ' || nullif(btrim(p_note), ''), ''));
  return (select d from public.rating_disputes d where d.id = p_dispute_id);
end;
$$;

-- Admin list with the rating's content.
drop view if exists public.admin_rating_disputes;
create view public.admin_rating_disputes with (security_invoker = true) as
select d.*,
  coalesce(sr.rating, ar.rating) as rating,
  coalesce(sr.text, ar.text) as review_text,
  case when d.review_type = 'studio_review' then sr.artist_name else ar.studio_name end as reviewer_name,
  case when d.review_type = 'studio_review' then st.name else ap.artist_name end as rated_name
from public.rating_disputes d
left join public.reviews sr on d.review_type = 'studio_review' and sr.id = d.review_id
left join public.studios st on st.id = sr.studio_id
left join public.artist_reviews ar on d.review_type = 'artist_review' and ar.id = d.review_id
left join public.artist_profiles ap on ap.id = ar.artist_id;

-- ---------------------------------------------------------------------
-- 20261004000001_studio_artist_links.sql
-- ---------------------------------------------------------------------
-- EasySesh: connect a studio to an artist profile (e.g. an artist who also runs a studio).
-- The studio asks, the artist confirms; both profiles then show the connection.

create table if not exists public.studio_artist_links (
  studio_id uuid primary key references public.studios (id) on delete cascade,
  artist_id uuid not null references public.profiles (id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'accepted')),
  created_at timestamptz not null default now()
);
create index if not exists studio_artist_links_artist_idx on public.studio_artist_links (artist_id);

alter table public.studio_artist_links enable row level security;
drop policy if exists "studio_artist_links: read" on public.studio_artist_links;
create policy "studio_artist_links: read" on public.studio_artist_links for select to authenticated
  using (status = 'accepted' or artist_id = auth.uid() or public.owns_studio(studio_id) or public.is_admin());

-- Studio owner asks an artist to connect profiles.
create or replace function public.request_studio_artist_link(p_artist_id uuid)
returns public.studio_artist_links
language plpgsql security definer set search_path = public
as $$
declare
  v_studio public.studios := (select s from public.studios s where s.owner_id = auth.uid() limit 1);
begin
  if v_studio.id is null or not public.owns_approved_studio(v_studio.id) then
    raise exception 'Only approved studios can connect an artist profile.';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_artist_id and p.role = 'artist' and p.status = 'active') then
    raise exception 'not_found';
  end if;
  insert into public.studio_artist_links (studio_id, artist_id, status)
  values (v_studio.id, p_artist_id, 'pending')
  on conflict (studio_id) do update set artist_id = excluded.artist_id, status = 'pending', created_at = now();
  perform public.notify(p_artist_id, 'system', 'Connect your studio?',
    v_studio.name || ' wants to show your artist profile on its page, and the studio on your profile. Confirm it on your profile.',
    null, null, v_studio.id);
  return (select l from public.studio_artist_links l where l.studio_id = v_studio.id);
end;
$$;

-- Artist confirms or declines a connection request.
create or replace function public.respond_studio_artist_link(p_studio_id uuid, p_accept boolean)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if p_accept then
    update public.studio_artist_links set status = 'accepted' where studio_id = p_studio_id and artist_id = auth.uid();
  else
    delete from public.studio_artist_links where studio_id = p_studio_id and artist_id = auth.uid();
  end if;
  if not found and p_accept then raise exception 'not_found'; end if;
end;
$$;

-- Either side removes the connection.
create or replace function public.remove_studio_artist_link(p_studio_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  delete from public.studio_artist_links l
  where l.studio_id = p_studio_id and (l.artist_id = auth.uid() or public.owns_studio(l.studio_id));
end;
$$;

-- ---------------------------------------------------------------------
-- 20261005000001_request_expiry.sql
-- ---------------------------------------------------------------------
-- EasySesh: booking requests (studios without instant booking) must be answered within 24 hours,
-- otherwise they expire and the artist is told. Studios are paid only after a completed session
-- (process-payouts schedules payouts for completed bookings only, 2 days after the session ends).

create or replace function public.run_booking_housekeeping()
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_expired record;
begin
  -- Unpaid holds release the slot after 30 minutes.
  update public.bookings set status = 'expired'
  where status = 'awaiting_payment' and created_at < now() - interval '30 minutes';

  -- Requests the studio didn't answer within 24 hours (or before the session starts) expire.
  -- Card authorisations are released by the edge function; cash bookings had nothing charged.
  for v_expired in
    update public.bookings set status = 'expired',
      payment_status = case when payment_method = 'cash' then 'unpaid'::public.payment_status else 'refunded'::public.payment_status end
    where status = 'pending_approval' and (starts_at < now() or created_at < now() - interval '24 hours')
    returning id, artist_id, studio_name
  loop
    perform public.notify(v_expired.artist_id, 'booking_declined', 'Request expired',
      v_expired.studio_name || ' didn''t answer within 24 hours, so your request expired. Nothing was charged.', v_expired.id);
  end loop;

  -- Finished sessions complete (triggers review prompt; payouts/balance charges run in process-payouts).
  update public.bookings set status = 'completed'
  where status = 'confirmed' and ends_at < now();
end;
$$;

-- ---------------------------------------------------------------------
-- 20261006000001_check_in.sql
-- ---------------------------------------------------------------------
-- EasySesh: optional check-in when the artist arrives, and the studio confirming the arrival.
-- Records time and (for the artist) how far the phone was from the studio, as evidence in
-- no-show or payment disputes. EasySesh recommends it; a studio can switch it off, in which case
-- EasySesh can't promise a refund if something goes wrong.

alter table public.bookings
  add column if not exists artist_checked_in_at timestamptz,
  add column if not exists artist_check_in_distance_m integer,
  add column if not exists studio_confirmed_arrival_at timestamptz;

-- Great-circle distance in metres.
create or replace function public.distance_m(p_lat1 double precision, p_lng1 double precision, p_lat2 double precision, p_lng2 double precision)
returns integer language sql immutable as $$
  select round(6371000 * 2 * asin(sqrt(
    power(sin(radians(p_lat2 - p_lat1) / 2), 2) +
    cos(radians(p_lat1)) * cos(radians(p_lat2)) * power(sin(radians(p_lng2 - p_lng1) / 2), 2)
  )))::int;
$$;

-- Artist checks in (from 60 minutes before the session until it ends). Location is optional.
create or replace function public.check_in_booking(p_booking_id uuid, p_lat double precision default null, p_lng double precision default null)
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
  v_studio public.studios;
  v_distance integer;
begin
  if v_booking.id is null or v_booking.artist_id <> auth.uid() then raise exception 'not_found'; end if;
  if v_booking.status <> 'confirmed' then raise exception 'Only confirmed bookings can be checked in.'; end if;
  if now() < v_booking.starts_at - interval '60 minutes' or now() > v_booking.ends_at then
    raise exception 'You can check in from 1 hour before your session until it ends.';
  end if;
  if v_booking.artist_checked_in_at is not null then return v_booking; end if;
  v_studio := (select s from public.studios s where s.id = v_booking.studio_id);
  -- Studios can switch check-in off (booking_policy.check_in_enabled); EasySesh recommends keeping it on.
  if not coalesce((v_studio.booking_policy ->> 'check_in_enabled')::boolean, true) then
    raise exception 'This studio has turned off check-in.';
  end if;
  if p_lat is not null and p_lng is not null then
    v_distance := public.distance_m(p_lat, p_lng, v_studio.latitude, v_studio.longitude);
  end if;
  update public.bookings set artist_checked_in_at = now(), artist_check_in_distance_m = v_distance
  where id = p_booking_id;
  perform public.notify(v_studio.owner_id, 'booking_changed', v_booking.artist_name || ' has arrived',
    'Checked in for ' || v_booking.session_type_name ||
      case when v_distance is null then '.' when v_distance <= 300 then ' at the studio.' else ' (' || v_distance || ' m from the studio).' end,
    v_booking.id, null, v_booking.studio_id);
  return (select b from public.bookings b where b.id = p_booking_id);
end;
$$;

-- Studio confirms the artist showed up.
create or replace function public.confirm_artist_arrival(p_booking_id uuid)
returns public.bookings
language plpgsql security definer set search_path = public
as $$
declare
  v_booking public.bookings := (select b from public.bookings b where b.id = p_booking_id);
begin
  if v_booking.id is null or not public.owns_approved_studio(v_booking.studio_id) then raise exception 'not_found'; end if;
  if v_booking.status not in ('confirmed', 'completed') then raise exception 'Only confirmed bookings can be marked as arrived.'; end if;
  if now() < v_booking.starts_at - interval '60 minutes' then raise exception 'The session hasn''t started yet.'; end if;
  update public.bookings set studio_confirmed_arrival_at = coalesce(studio_confirmed_arrival_at, now()) where id = p_booking_id;
  return (select b from public.bookings b where b.id = p_booking_id);
end;
$$;

-- ---------------------------------------------------------------------
-- 20261007000001_changelog_terms_updates.sql
-- ---------------------------------------------------------------------
-- EasySesh: admins publish a changelog ("What's new" in the app). An entry can also be marked as a
-- legal update: every user must then read the documents again and accept them before they can
-- keep using the app.

create table if not exists public.app_changelog (
  id uuid primary key default gen_random_uuid(),
  version text not null,
  title text not null,
  body text not null default '',
  -- 'all', 'artist' or 'studio_owner'
  audience text not null default 'all' check (audience in ('all', 'artist', 'studio_owner')),
  is_legal_update boolean not null default false,
  published_at timestamptz not null default now(),
  created_by uuid references public.profiles(id) on delete set null
);
create index if not exists app_changelog_published_idx on public.app_changelog (published_at desc);

alter table public.app_changelog enable row level security;
drop policy if exists "changelog: everyone reads" on public.app_changelog;
create policy "changelog: everyone reads" on public.app_changelog for select using (published_at <= now());
-- No insert/update/delete policies: admins write through the functions below.

-- The terms version everyone must have accepted. The app ships a version too and asks for
-- whichever is newer.
create table if not exists public.app_terms (
  id boolean primary key default true check (id),
  version text not null,
  updated_at timestamptz not null default now()
);
-- 2026-09-26: terms, privacy, refunds, studio agreement and guidelines updated (check-in, cash
-- refunds, fee collection, promotions, moderation) – everyone accepts again.
insert into public.app_terms (id, version) values (true, '2026-09-26')
  on conflict (id) do update set version = greatest(public.app_terms.version, excluded.version), updated_at = now();
alter table public.app_terms enable row level security;
drop policy if exists "terms: everyone reads" on public.app_terms;
create policy "terms: everyone reads" on public.app_terms for select using (true);

create or replace function public.current_terms_version()
returns text language sql stable security definer set search_path = public as $$
  select version from public.app_terms where id;
$$;
grant execute on function public.current_terms_version() to anon, authenticated;

-- Accepting records the version and time. Accepting an older version than the current one is refused.
create or replace function public.accept_terms(p_version text)
returns public.profiles
language plpgsql security definer set search_path = public
as $$
declare
  p public.profiles;
begin
  if coalesce(trim(p_version), '') = '' then raise exception 'Missing terms version.'; end if;
  if p_version < public.current_terms_version() then
    raise exception 'Please update the app to read and accept the latest terms.';
  end if;
  update public.profiles set accepted_terms_version = p_version, accepted_terms_at = now()
  where id = auth.uid();
  p := (select x from public.profiles x where x.id = auth.uid());
  if p.id is null then raise exception 'not_found'; end if;
  return p;
end;
$$;

-- Admin: publish an entry. A legal update bumps the terms version (to today's date, or a later
-- one if today's was already used), so everyone is asked to accept again.
create or replace function public.admin_publish_changelog(p_version text, p_title text, p_body text,
  p_audience text default 'all', p_legal_update boolean default false)
returns public.app_changelog
language plpgsql security definer set search_path = public
as $$
declare
  v_entry public.app_changelog;
  v_terms text;
begin
  perform public.require_admin();
  if coalesce(trim(p_title), '') = '' then raise exception 'Give the update a title.'; end if;
  if p_legal_update then
    v_terms := to_char(now() at time zone 'utc', 'YYYY-MM-DD');
    if v_terms <= public.current_terms_version() then
      v_terms := public.current_terms_version() || '.' || to_char(clock_timestamp(), 'HH24MISS');
    end if;
    update public.app_terms set version = v_terms, updated_at = now() where id;
  end if;
  v_entry.id := gen_random_uuid();
  insert into public.app_changelog (id, version, title, body, audience, is_legal_update, created_by)
  values (v_entry.id, coalesce(nullif(trim(p_version), ''), coalesce(v_terms, to_char(now(), 'YYYY-MM-DD'))),
          trim(p_title), coalesce(p_body, ''), coalesce(p_audience, 'all'), p_legal_update, auth.uid());
  v_entry := (select x from public.app_changelog x where x.id = v_entry.id);
  return v_entry;
end;
$$;

create or replace function public.admin_delete_changelog(p_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  delete from public.app_changelog where id = p_id;
end;
$$;

-- How many users have accepted the current terms (for the admin dashboard).
create view public.admin_terms_status with (security_invoker = true) as
  select public.current_terms_version() as version,
         count(*) filter (where p.accepted_terms_version >= public.current_terms_version()) as accepted,
         count(*) filter (where p.role <> 'admin') as total
  from public.profiles p
  where public.is_trusted() and p.role <> 'admin';

-- ---------------------------------------------------------------------
-- 20261008000001_moderation.sql
-- ---------------------------------------------------------------------
-- EasySesh: moderation tools for admins.
--  • Warnings: shown to the user in the app until they acknowledge them.
--  • Suspensions and bans for a chosen period (1, 3, 7 days or custom) or indefinitely.
--    They lift automatically when the period ends.
--  • A moderation history per user and studio (warnings, suspensions, bans, reports).

alter table public.profiles add column if not exists status_until timestamptz;
alter table public.studios add column if not exists suspended_until timestamptz;

-- Users can never change these themselves.
create or replace function public.guard_profile_moderation()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then new.status_until := old.status_until; end if;
  return new;
end;
$$;
drop trigger if exists guard_profile_moderation on public.profiles;
create trigger guard_profile_moderation before update on public.profiles
  for each row execute function public.guard_profile_moderation();

create or replace function public.guard_studio_moderation()
returns trigger language plpgsql as $$
begin
  if not public.is_trusted() then
    if tg_op = 'INSERT' then new.suspended_until := null; else new.suspended_until := old.suspended_until; end if;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_studio_moderation on public.studios;
create trigger guard_studio_moderation before insert or update on public.studios
  for each row execute function public.guard_studio_moderation();

create table if not exists public.moderation_actions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  studio_id uuid references public.studios (id) on delete set null,
  -- warning | suspension | ban | lifted
  action text not null check (action in ('warning', 'suspension', 'ban', 'lifted')),
  reason text not null default '',
  ends_at timestamptz,
  acknowledged_at timestamptz,
  actor_id uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists moderation_actions_user_idx on public.moderation_actions (user_id, created_at desc);
create index if not exists moderation_actions_studio_idx on public.moderation_actions (studio_id, created_at desc);

alter table public.moderation_actions enable row level security;
drop policy if exists "moderation: own or admin" on public.moderation_actions;
create policy "moderation: own or admin" on public.moderation_actions for select
  using (user_id = auth.uid() or public.is_trusted());

-- Admin: warn a user (and optionally name the studio it's about).
create or replace function public.admin_warn(p_user_id uuid, p_reason text, p_studio_id uuid default null)
returns public.moderation_actions
language plpgsql security definer set search_path = public
as $$
declare
  v_row public.moderation_actions;
begin
  perform public.require_admin();
  if coalesce(trim(p_reason), '') = '' then raise exception 'Write what the warning is about.'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then raise exception 'not_found'; end if;
  v_row.id := gen_random_uuid();
  insert into public.moderation_actions (id, user_id, studio_id, action, reason, actor_id)
  values (v_row.id, p_user_id, p_studio_id, 'warning', trim(p_reason), auth.uid());
  v_row := (select x from public.moderation_actions x where x.id = v_row.id);
  perform public.notify(p_user_id, 'system', 'Warning from EasySesh', trim(p_reason), null, null, p_studio_id);
  return v_row;
end;
$$;

-- Admin: suspend or ban an account for p_days days (null = until lifted), or lift it.
-- p_action: 'suspend' | 'ban' | 'lift'. Fractions of a day are allowed (0.5 = 12 hours).
create or replace function public.admin_moderate_user(p_user_id uuid, p_action text, p_days numeric default null, p_reason text default null)
returns public.profiles
language plpgsql security definer set search_path = public
as $$
declare
  p public.profiles;
  v_until timestamptz := case when p_days is null then null else now() + make_interval(secs => (p_days * 86400)::double precision) end;
begin
  perform public.require_admin();
  if p_user_id = auth.uid() then raise exception 'You cannot change your own status.'; end if;
  if p_action not in ('suspend', 'ban', 'lift') then raise exception 'Unknown action.'; end if;
  if p_days is not null and p_days <= 0 then raise exception 'Choose a period longer than zero.'; end if;

  if p_action = 'lift' then
    update public.profiles set status = 'active', status_until = null, status_reason = null where id = p_user_id;
    p := (select x from public.profiles x where x.id = p_user_id);
    if p.id is null then raise exception 'not_found'; end if;
    update public.studios set is_active = true where owner_id = p_user_id and status = 'approved';
    insert into public.moderation_actions (user_id, action, reason, actor_id) values (p_user_id, 'lifted', coalesce(p_reason, ''), auth.uid());
    perform public.notify(p_user_id, 'system', 'Your account is active again', coalesce(nullif(trim(p_reason), ''), 'You can use EasySesh again.'), null, null, null);
    return p;
  end if;

  update public.profiles
     set status = case when p_action = 'ban' then 'banned'::public.account_status else 'suspended'::public.account_status end,
         status_until = v_until, status_reason = p_reason
   where id = p_user_id;
  p := (select x from public.profiles x where x.id = p_user_id);
  if p.id is null then raise exception 'not_found'; end if;
  update public.studios set is_active = false where owner_id = p_user_id;
  delete from public.device_tokens where user_id = p_user_id;
  insert into public.moderation_actions (user_id, action, reason, ends_at, actor_id)
  values (p_user_id, case when p_action = 'ban' then 'ban' else 'suspension' end, coalesce(p_reason, ''), v_until, auth.uid());
  return p;
end;
$$;

-- Admin: suspend a studio listing for a period (null = until lifted), or lift it.
create or replace function public.admin_moderate_studio(p_studio_id uuid, p_action text, p_days numeric default null, p_reason text default null)
returns public.studios
language plpgsql security definer set search_path = public
as $$
declare
  s public.studios := (select x from public.studios x where x.id = p_studio_id);
  v_until timestamptz := case when p_days is null then null else now() + make_interval(secs => (p_days * 86400)::double precision) end;
begin
  perform public.require_admin();
  if s.id is null then raise exception 'not_found'; end if;
  if p_action not in ('suspend', 'lift') then raise exception 'Unknown action.'; end if;
  if p_days is not null and p_days <= 0 then raise exception 'Choose a period longer than zero.'; end if;

  if p_action = 'lift' then
    if s.status = 'suspended' then
      update public.studios set status = 'approved', is_active = true, suspended_until = null where id = s.id;
      insert into public.studio_status_events (studio_id, from_status, to_status, note, actor_id) values (s.id, 'suspended', 'approved', p_reason, auth.uid());
    end if;
    insert into public.moderation_actions (user_id, studio_id, action, reason, actor_id) values (s.owner_id, s.id, 'lifted', coalesce(p_reason, ''), auth.uid());
    perform public.notify(s.owner_id, 'system', 'Your studio is visible again', coalesce(nullif(trim(p_reason), ''), 'Artists can find and book your studio again.'), null, null, s.id);
  else
    update public.studios set status = 'suspended', is_active = false, suspended_until = v_until, admin_note = coalesce(p_reason, admin_note) where id = s.id;
    insert into public.studio_status_events (studio_id, from_status, to_status, note, actor_id) values (s.id, s.status, 'suspended', p_reason, auth.uid());
    insert into public.moderation_actions (user_id, studio_id, action, reason, ends_at, actor_id) values (s.owner_id, s.id, 'suspension', coalesce(p_reason, ''), v_until, auth.uid());
    perform public.notify(s.owner_id, 'system', 'Your studio has been suspended',
      coalesce(nullif(trim(p_reason), ''), 'Your studio breaks our rules.') ||
      case when v_until is null then ' It stays hidden until our team lifts the suspension.'
           else ' It is hidden until ' || to_char(v_until, 'DD Mon YYYY HH24:MI') || ' (UTC).' end,
      null, null, s.id);
  end if;
  return (select x from public.studios x where x.id = s.id);
end;
$$;

-- Ends suspensions and bans whose period is over. Runs every 5 minutes; users whose period just
-- ended can also trigger it for themselves when they sign in.
create or replace function public.lift_expired_moderation()
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_user uuid;
  v_studio public.studios;
begin
  for v_user in select id from public.profiles where status <> 'active' and status_until is not null and status_until <= now() loop
    update public.profiles set status = 'active', status_until = null, status_reason = null where id = v_user;
    update public.studios set is_active = true where owner_id = v_user and status = 'approved';
    insert into public.moderation_actions (user_id, action, reason) values (v_user, 'lifted', 'Period ended');
  end loop;
  for v_studio in select * from public.studios where status = 'suspended' and suspended_until is not null and suspended_until <= now() loop
    update public.studios set status = 'approved', is_active = true, suspended_until = null where id = v_studio.id;
    insert into public.studio_status_events (studio_id, from_status, to_status, note) values (v_studio.id, 'suspended', 'approved', 'Suspension period ended');
    insert into public.moderation_actions (user_id, studio_id, action, reason) values (v_studio.owner_id, v_studio.id, 'lifted', 'Period ended');
    perform public.notify(v_studio.owner_id, 'system', 'Your studio is visible again', 'The suspension period has ended.', null, null, v_studio.id);
  end loop;
end;
$$;
revoke execute on function public.lift_expired_moderation() from public, anon, authenticated;

create or replace function public.lift_my_expired_restriction()
returns public.profiles
language plpgsql security definer set search_path = public
as $$
declare
  p public.profiles := (select x from public.profiles x where x.id = auth.uid());
begin
  if p.id is not null and p.status <> 'active' and p.status_until is not null and p.status_until <= now() then
    update public.profiles set status = 'active', status_until = null, status_reason = null where id = p.id;
    p := (select x from public.profiles x where x.id = p.id);
    update public.studios set is_active = true where owner_id = p.id and status = 'approved';
    insert into public.moderation_actions (user_id, action, reason) values (p.id, 'lifted', 'Period ended');
  end if;
  return p;
end;
$$;

-- The user confirms they've read a warning.
create or replace function public.acknowledge_warning(p_id uuid)
returns void
language sql security definer set search_path = public
as $$
  update public.moderation_actions set acknowledged_at = now()
  where id = p_id and user_id = auth.uid() and acknowledged_at is null;
$$;

select cron.schedule('easysesh-lift-moderation', '*/5 * * * *', $$select public.lift_expired_moderation()$$);

-- Everything moderation-related for a user or their studio, newest first (admin dashboard).
create view public.admin_moderation_history with (security_invoker = true) as
select m.id, m.user_id, m.studio_id, m.action as kind, m.reason as details, m.ends_at, m.acknowledged_at,
       m.created_at, ap.email as actor_email
  from public.moderation_actions m
  left join public.profiles ap on ap.id = m.actor_id
union all
select r.id, case when r.target_type = 'user' then r.target_id else s.owner_id end,
       case when r.target_type = 'studio' then r.target_id end,
       'report' as kind, r.reason::text || coalesce(': ' || nullif(r.details, ''), '') || coalesce(' → ' || r.status::text || coalesce(' (' || r.admin_note || ')', ''), ''),
       null, null, r.created_at, null
  from public.reports r
  left join public.studios s on r.target_type = 'studio' and s.id = r.target_id
 where r.target_type in ('user', 'studio')
union all
select e.id, s.owner_id, e.studio_id, 'studio_status' as kind,
       coalesce(e.from_status::text, '–') || ' → ' || e.to_status::text || coalesce(': ' || e.note, ''),
       null, null, e.created_at, ap.email
  from public.studio_status_events e
  join public.studios s on s.id = e.studio_id
  left join public.profiles ap on ap.id = e.actor_id;

-- The users list gains the end of the current suspension and a count of warnings.
drop view if exists public.admin_users;
create view public.admin_users with (security_invoker = true) as
select p.id, p.email, p.role, p.status, p.status_reason, p.status_until, p.is_verified, p.created_at,
  a.artist_name, a.city as artist_city,
  s.id as studio_id, s.name as studio_name,
  coalesce(a.has_admin_badge, s.has_admin_badge, false) as has_admin_badge,
  (select count(*) from public.bookings b where b.artist_id = p.id) as booking_count,
  (select count(*) from public.moderation_actions m where m.user_id = p.id and m.action = 'warning') as warning_count
from public.profiles p
left join public.artist_profiles a on a.id = p.id
left join public.studios s on s.owner_id = p.id;

-- Admin: cancel a studio's pending promotion order (e.g. never paid).
create or replace function public.admin_cancel_promotion(p_promotion_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  perform public.require_admin();
  update public.studio_promotions set status = 'cancelled' where id = p_promotion_id and status = 'pending';
  if not found then raise exception 'This order is not pending.'; end if;
end;
$$;

-- ---------------------------------------------------------------------
-- 20261009000001_rename_cron_jobs.sql
-- ---------------------------------------------------------------------
-- EasySesh: scheduled jobs were renamed from "sonora-*" to "easysesh-*". Schedule every job
-- under its new name (same schedule as before; scheduling a name again just updates it), then
-- remove the old names so nothing runs twice.
select cron.schedule('easysesh-booking-housekeeping', '*/10 * * * *', $$select public.run_booking_housekeeping()$$);
select cron.schedule('easysesh-session-reminders', '*/15 * * * *', $$select public.queue_session_reminders()$$);
select cron.schedule('easysesh-process-payouts', '7 * * * *', $$select public.call_edge_function('process-payouts')$$);
select cron.schedule('easysesh-cash-housekeeping', '17 * * * *', $$select public.run_cash_housekeeping()$$);

do $$
declare
  v_job text;
begin
  for v_job in select jobname from cron.job where jobname like 'sonora-%' loop
    perform cron.unschedule(v_job);
  end loop;
exception when others then
  raise notice 'Old scheduled jobs not removed: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------
-- 20261010000001_export_my_data.sql
-- ---------------------------------------------------------------------
-- EasySesh: "Download my data" (GDPR art. 15/20) straight from the database, so it works without
-- the export-data edge function being deployed. Returns everything stored about the caller.
create or replace function public.export_my_data()
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_id uuid := auth.uid();
  v_studios uuid[];
  v_bookings uuid[];
begin
  if v_id is null then raise exception 'not_authenticated'; end if;
  v_studios := array(select id from public.studios where owner_id = v_id);
  v_bookings := array(select id from public.bookings where artist_id = v_id or studio_id = any(v_studios));

  return jsonb_build_object(
    'exported_at', now(),
    'notice', 'This file contains the personal data EasySesh holds about you (GDPR art. 15 and 20). Card numbers are held by Stripe and never stored by EasySesh.',
    'account', (select to_jsonb(p) - 'stripe_customer_id' from public.profiles p where p.id = v_id),
    'artist_profile', (select to_jsonb(a) from public.artist_profiles a where a.id = v_id),
    'studios', coalesce((select jsonb_agg(to_jsonb(s)) from public.studios s where s.id = any(v_studios)), '[]'),
    'bookings_as_artist', coalesce((select jsonb_agg(to_jsonb(b) order by b.starts_at) from public.bookings b where b.artist_id = v_id), '[]'),
    'bookings_at_my_studio', coalesce((select jsonb_agg(to_jsonb(b) order by b.starts_at) from public.bookings b where b.studio_id = any(v_studios)), '[]'),
    'payments', coalesce((select jsonb_agg(jsonb_build_object(
        'booking_id', t.booking_id, 'kind', t.kind, 'method', t.method, 'status', t.status, 'amount', t.amount,
        'currency', t.currency, 'receipt_number', t.receipt_number, 'card_brand', t.card_brand, 'card_last4', t.card_last4,
        'created_at', t.created_at) order by t.created_at)
      from public.transactions t where t.booking_id = any(v_bookings)), '[]'),
    'payouts', coalesce((select jsonb_agg(to_jsonb(p) order by p.scheduled_for) from public.payouts p where p.studio_id = any(v_studios)), '[]'),
    'platform_fees', coalesce((select jsonb_agg(to_jsonb(f) order by f.created_at) from public.studio_fee_ledger f where f.studio_id = any(v_studios)), '[]'),
    'fee_invoices', coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at) from public.studio_fee_invoices i where i.studio_id = any(v_studios)), '[]'),
    'conversations', coalesce((select jsonb_agg(to_jsonb(c)) from public.conversations c where c.artist_id = v_id or c.studio_id = any(v_studios)), '[]'),
    'messages_sent', coalesce((select jsonb_agg(jsonb_build_object('conversation_id', m.conversation_id, 'kind', m.kind, 'body', m.body, 'created_at', m.created_at) order by m.created_at)
      from public.messages m where m.sender_id = v_id), '[]'),
    'support_requests', coalesce((select jsonb_agg(to_jsonb(t) || jsonb_build_object('messages',
        coalesce((select jsonb_agg(jsonb_build_object('from_admin', sm.from_admin, 'body', sm.body, 'created_at', sm.created_at) order by sm.created_at)
          from public.support_messages sm where sm.ticket_id = t.id), '[]')))
      from public.support_tickets t where t.user_id = v_id), '[]'),
    'reviews_written', coalesce((select jsonb_agg(to_jsonb(r)) from public.reviews r where r.artist_id = v_id), '[]'),
    'ratings_from_studios', coalesce((select jsonb_agg(to_jsonb(r)) from public.artist_reviews r where r.artist_id = v_id), '[]'),
    'ratings_given_to_artists', coalesce((select jsonb_agg(to_jsonb(r)) from public.artist_reviews r where r.studio_id = any(v_studios)), '[]'),
    'reports_made', coalesce((select jsonb_agg(to_jsonb(r)) from public.reports r where r.reporter_id = v_id), '[]'),
    'moderation', coalesce((select jsonb_agg(jsonb_build_object('action', m.action, 'reason', m.reason, 'ends_at', m.ends_at, 'created_at', m.created_at) order by m.created_at)
      from public.moderation_actions m where m.user_id = v_id), '[]'),
    'notifications', coalesce((select jsonb_agg(to_jsonb(n) order by n.created_at) from public.notifications n where n.user_id = v_id), '[]'),
    'devices', coalesce((select jsonb_agg(jsonb_build_object('platform', d.platform, 'created_at', d.created_at)) from public.device_tokens d where d.user_id = v_id), '[]')
  );
end;
$$;
revoke execute on function public.export_my_data() from public, anon;
grant execute on function public.export_my_data() to authenticated;

-- ---------------------------------------------------------------------
-- Accounts that already exist in auth (e.g. when re-running this file)
-- get their profile rows back.
-- ---------------------------------------------------------------------
insert into public.profiles (id, email, role)
select u.id, coalesce(u.email, ''),
  case when u.raw_user_meta_data ->> 'role' = 'studio_owner' then 'studio_owner'::public.user_role else 'artist'::public.user_role end
from auth.users u
on conflict (id) do nothing;
insert into public.artist_profiles (id)
select p.id from public.profiles p where p.role = 'artist'
on conflict (id) do nothing;

-- ---------------------------------------------------------------------
-- Grants: the app signs in as "authenticated". Row-level security above
-- decides which rows each user can see or change.
-- ---------------------------------------------------------------------
grant usage on schema public to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to authenticated, service_role;
grant select on public.platform_settings to anon;
grant execute on all functions in schema public to authenticated, service_role;
revoke execute on function public.notify, public.booking_system_message, public.call_edge_function,
  public.notify_payment_problem, public.add_support_message, public.activate_promotion,
  public.expire_promotions, public.create_fee_invoices, public.run_fee_enforcement,
  public.refresh_artist_rating, public.lift_expired_moderation from anon, authenticated;

